/* A121 staged author data; promote only after full manifest and registry audit. */
(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('scald','Scald comes through Old French eschalder from Latin excaldare, “wash in hot water”; it can mean burn skin with hot liquid, clean a vessel with boiling water, or the resulting injury.',[C('scald.s1','烫伤皮肤','Steam from the uncovered kettle scalded Ben’s wrist when he reached across the counter.','本伸手越过台面时，被敞口水壶冒出的蒸汽烫伤了手腕。','Steam from the kettle scalded Ben’s wrist / when he reached / across the counter.','scald.s1 指被很热的液体或蒸汽烫伤。','蒸汽使本的手腕受伤。'),C('scald.s2','用沸水烫洗','Before filling the jam jar, scald it with boiling water to remove germs from the inside.','装果酱前，用沸水烫洗罐子内部以去除细菌。','Scald the jam jar with boiling water / before filling it / to remove germs.','scald.s2 指把沸水倒入容器并冲洗消毒。','玻璃罐用沸水烫洗。'),C('scald.s3','烫伤处；烫伤','The nurse cooled the scald on the child’s arm under clean running water.','护士用干净的流动水冷却孩子手臂上的烫伤处。','The nurse cooled the scald / on the child’s arm / under running water.','scald.s3 作名词，指热液体或蒸汽造成的伤口。','护士处理手臂上的烫伤。')],M('Steam scalded Ben by leaving his wrist cool and completely uninjured.','Steam scalded Ben by burning the skin on his wrist.','皮肤没有受伤就不是烫伤。','meaning'),[q('What injured Ben’s wrist?','steam from the uncovered kettle','boiling water used to clean a jar','a scald on a child’s arm','水壶蒸汽烫伤了本的手腕。',1,'context'),q('What should be done to the jam jar before filling it?','rinse it with boiling water','touch it with a hot wrist','cool a scald under running water','装果酱前要用沸水烫洗玻璃罐。',2,'context'),q('What did the nurse cool?','a burn caused by hot liquid or steam','a jam jar before filling it','a kettle that was not hot','护士用水冷却孩子手臂上的烫伤。',3,'context'),q('What does scald mean in “steam scalded Ben”?','burn the skin with hot liquid or steam','clean a container with boiling water','an injury caused by hot liquid','这里 scald 是动词，指蒸汽烫伤皮肤。',1,'meaning')]);
P('scale','Scale has related and separate histories: the size/measuring senses come through Latin scala (“ladder”), while musical scales and fish scales have distinct origins; it can also mean climb.',[C('scale.s1','规模；范围；程度','The project expanded its scale from one neighborhood to the entire county after the pilot succeeded.','试点成功后，项目从一个街区扩大到了整个县。','The project expanded its scale / from one neighborhood / to the county.','scale.s1 指某事的大小、范围或程度。','项目覆盖范围扩大。'),C('scale.s2','等级；刻度；比例','The map uses a scale of one centimeter to five kilometers, so the road distances can be compared.','地图采用一厘米代表五公里的比例尺，因此可以比较道路距离。','The map uses a scale / of one centimeter to five kilometers / to compare distances.','scale.s2 指用于测量或比较的一系列标记、数字或比例。','比例尺说明地图距离和实际距离的关系。'),C('scale.s3','秤；天平','Place the parcel on the scale before printing the postage label.','打印邮资标签前，把包裹放到秤上。','Place the parcel on the scale / before printing / the postage label.','scale.s3 指称量物体的仪器。','包裹放在秤上称重。'),C('scale.s4','音阶','The pianist practiced the C-major scale slowly before playing the full piece.','钢琴家先慢慢练习C大调音阶，再演奏整首曲子。','The pianist practiced the C-major scale / slowly / before the full piece.','scale.s4 指按固定顺序排列的一组音符。','钢琴家练习一组音符。'),C('scale.s5','鳞；鳞片','A silver scale from the fish caught the light as the fisherman cleaned it beside the boat.','渔夫在船边清理鱼时，一片银色鱼鳞闪着光。','A silver scale from the fish / caught the light / during cleaning.','scale.s5 指鱼或爬行动物身上的小硬片。','鱼鳞反射出光。'),C('scale.s6','攀登；翻过','The climbers scaled the cliff using fixed ropes and reached the ledge before sunset.','攀登者借助固定绳索爬上峭壁，在日落前抵达岩架。','The climbers scaled the cliff / using fixed ropes / before sunset.','scale.s6 作动词，指攀登高处。','攀登者爬上峭壁。')],M('The climbers scaled the cliff by staying at its base and never climbing upward.','The climbers scaled the cliff by climbing up its steep face to the ledge.','待在山脚没有向上攀登，不能说 scaled the cliff。','meaning'),[q('How far did the project’s scale expand?','from one neighborhood to the entire county','from a county to one street','from a piano to a map','项目从一个街区扩展到整个县。',1,'context'),q('What does the map scale show?','the relationship between map and real distances','the parcel’s weight','the notes in a piano exercise','地图比例尺说明图上距离与实际距离的比例。',2,'context'),q('Which instrument weighs the parcel?','a scale','a C-major scale','a fish scale','包裹要放在秤上称重。',1,'meaning'),q('What did the pianists practice?','a fixed sequence of musical notes','the size of a county project','a cliff face','钢琴家练习C大调音阶。',4,'context')]);
P('scaled','Scaled is the past participle of scale; it can describe an animal covered with scales or an object adjusted in size according to a scale.',[C('scaled.s1','有鳞的','The scaled lizard rested on a warm rock, its small plates protecting the skin along its back.','这只有鳞的蜥蜴趴在温暖的石头上，背部的小鳞片保护着皮肤。','The scaled lizard rested on a rock / its small plates / protecting its back.','scaled.s1 指身体覆盖着鳞片的动物。','蜥蜴背部覆盖小鳞片。'),C('scaled.s2','按比例调整的','The scaled model is one-fifth the height of the planned tower but preserves the same proportions.','这个按比例缩小的模型只有计划中塔楼的五分之一高，但保持了相同比例。','The scaled model is one-fifth as tall / while preserving / the same proportions.','scaled.s2 指依据比例尺调整过大小的。','模型按比例缩小。')],M('The scaled lizard had smooth bare skin and no protective plates on its back.','The scaled lizard had small protective plates covering its skin.','没有鳞片覆盖的光滑皮肤不符合 scaled 的动物义。','meaning'),[q('What protected the lizard’s back?','small scales on its skin','a one-fifth model','a C-major scale','蜥蜴背部的小鳞片保护着皮肤。',1,'context'),q('How tall was the scaled model compared with the planned tower?','one-fifth as tall','the same height and size','five times taller','模型高度是计划中塔楼的五分之一。',2,'context'),q('What does scaled mean about the lizard?','covered with small hard plates','adjusted to a measured proportion','climbed to a high place','scaled lizard 指身上覆盖鳞片的蜥蜴。',1,'meaning'),q('What does scaled mean about the model?','adjusted in size according to a proportion','covered in fish scales','measured on a weighing device','scaled model 指按比例调整大小的模型。',2,'meaning')]);
P('scalpel','Scalpel comes from Latin scalpellum, a small cutting or scraping knife; it is an extremely sharp short-bladed instrument used in surgery and dissection.',C('scalpel.s1','手术刀','The surgeon replaced the scalpel after the procedure and placed the used blade in a marked sharps container.','手术结束后，外科医生更换了手术刀，并把用过的刀片放入标记清晰的锐器盒。','The surgeon replaced the scalpel / after the procedure / and disposed of its blade safely.','scalpel 指手术或解剖时使用的短而极锋利的刀。','手术刀片使用后安全处置。'),M('The surgeon used a scalpel to stitch the wound with blunt thread and never cut or dissect tissue.','The surgeon used a scalpel, a very sharp short-bladed knife, to make the incision.','手术刀用于切开组织，而不是缝合钝线。','meaning'),[q('Where did the surgeon place the used blade?','in a marked sharps container','on the weighing scale','inside a jam jar','用过的手术刀片被放入锐器盒。',1,'context'),q('What is a scalpel designed to do?','make precise cuts in surgery or dissection','weigh a parcel','measure a map’s distance','scalpel 是用于手术或解剖切割的锋利短刀。',1,'meaning'),q('Why was the scalpel replaced after the procedure?','its used blade needed safe disposal','the ruler was too short','the jam jar needed scalding','用过的刀片需要安全处置。',1,'context'),q('Which object is a scalpel?','a short, extremely sharp surgical knife','a blunt stitching thread','a measuring scale','手术中使用的短而锋利的刀是 scalpel。',1,'meaning')]);
P('scam','Scam is an informal word for a deceptive trick to obtain money; its deeper origin is uncertain.',C('scam.s1','骗局','The email was a scam: it promised a prize but demanded a bank password before releasing it.','这封邮件是骗局：它承诺发奖，却要求先提供银行密码。','The email was a scam / promising a prize / in exchange for a bank password.','scam 指利用欺骗手段骗取钱财的把戏。','虚假中奖要求密码是骗局。'),M('The prize offer was a scam because the organizer gave the award without requesting money, passwords, or personal data.','The prize offer was a scam because it demanded a bank password before releasing the supposed award.','不要求钱财或敏感信息且实际发奖，不符合诈骗骗局的特征。','meaning'),[q('What did the email demand before releasing the prize?','a bank password','a ruler and a map','a C-major scale','邮件要求提供银行密码，显示这是骗局。',1,'context'),q('What is a scam?','a deceptive trick, often to get money','a sharp instrument used in surgery','a scale used to weigh objects','scam 指通常以骗钱为目的的欺诈把戏。',1,'meaning'),q('Which offer is a scam?','a fake prize that asks for card details first','a free award delivered without conditions','a clinic’s routine appointment reminder','先要求银行卡信息的虚假中奖通知是骗局。',1,'context'),q('What is known about the deeper origin of scam?','it is uncertain','it definitely comes from a surgical Latin word','it is a plural form of scale','scam 的更深层词源尚不确定。',1,'word-formation')]);
P('scamper','Scamper is an expressive verb recorded in English for quick, light movement; its deeper origin is uncertain.',C('scamper.s1','疾走；蹦跳','The puppies scampered across the lawn with quick, light steps when their owner opened the gate.','主人打开门后，小狗们迈着轻快的小步在草坪上蹦跑。','The puppies scampered across the lawn / with quick, light steps / after the gate opened.','scamper 指用轻快、急促的小步快速移动。','小狗兴奋地蹦跑过草坪。'),M('The puppies scampered across the lawn by moving slowly and heavily without lifting their feet.','The puppies scampered across the lawn with quick, light steps.','拖着脚缓慢沉重地移动不符合轻快蹦跑。','meaning'),[q('What did the puppies do when the gate opened?','ran across the lawn with quick, light steps','walked slowly without lifting their feet','climbed a cliff with fixed ropes','小狗们轻快地蹦跑过草坪。',1,'context'),q('What does scamper describe?','quick, light movement','a long, slow climb','a painful burn','scamper 描写轻快急促的移动。',1,'meaning'),q('Which animal might scamper?','a playful puppy darting across grass','a heavy cart rolling slowly','a lizard sleeping on a warm rock','小狗轻快地跑过草地可用 scamper 描写。',1,'context'),q('What is known about scamper’s deeper origin?','it is uncertain','it comes from Latin scala, “ladder”','it is the plural of scalpel','scamper 的更深层词源尚不确定。',1,'word-formation')]);
P('scan','Scan comes through Latin scandere, “climb,” first used of measuring poetic feet; today it can mean look over quickly, copy/read by a scanner, or examine the body medically.',[C('scan.s1','扫视；浏览','She scanned the crowded noticeboard for her name before the meeting began.','会议开始前，她快速浏览拥挤的公告栏，寻找自己的名字。','She scanned the noticeboard / for her name / before the meeting.','scan.s1 指快速查看各部分以寻找某物。','她扫视公告栏找名字。'),C('scan.s2','扫描；用扫描仪复制','The librarian scanned the signed page and saved a digital copy for the archive.','图书管理员扫描签名页，并为档案保存一份数字副本。','The librarian scanned the page / and saved / a digital copy.','scan.s2 指用光束扫描来复制图像或读取数据。','纸页被数字化存档。'),C('scan.s3','（医学）扫描检查','The doctor ordered a scan of the patient’s knee after the fall to check for internal damage.','患者摔倒后，医生安排对膝盖进行扫描检查，以确认内部是否受损。','The doctor ordered a scan / of the patient’s knee / after the fall.','scan.s3 指通过成像检查身体内部的医学检查。','医生安排膝部成像检查。')],M('She scanned the noticeboard by staring at one blank corner and never looking for the name.','She scanned the noticeboard by quickly checking its sections for her name.','只盯着空白处而不查找名字不是扫视公告栏。','meaning'),[q('What was she looking for on the noticeboard?','her name','a digital signature','damage inside her knee','她快速浏览公告栏寻找自己的名字。',1,'context'),q('What did the librarian do with the signed page?','made a digital copy','ordered a medical test','looked at the blank corner only','图书管理员扫描签名页并保存数字副本。',2,'context'),q('Why did the doctor order a scan?','to check the knee for internal damage','to copy a noticeboard into the archive','to find a name before a meeting','医生安排成像检查以确认膝盖是否内部受损。',3,'context'),q('Which use of scan means “look quickly over”?','scan a crowded noticeboard','scan a page into a digital archive','scan a patient’s knee medically','第一句中的 scan 指快速浏览。',1,'meaning')]);
P('scandal','Scandal comes from Greek skandalon, “stumbling block,” through Latin and French; it means shocking or dishonest behavior, or strong indignation at such behavior.',[C('scandal.s1','丑闻；丑事','The bribery scandal forced the mayor to resign after investigators published the payment records.','调查人员公布付款记录后，贿赂丑闻迫使市长辞职。','The bribery scandal forced the mayor to resign / after records / became public.','scandal.s1 指令人震惊或不诚实的事件。','贿赂事件曝光成为丑闻。'),C('scandal.s2','耻辱；愤慨','It was a scandal that the clinic had no clean water while the nearby hotel filled its swimming pool daily.','诊所没有干净用水，而附近酒店每天给泳池注水，这令人愤慨。','It was a scandal / that the clinic lacked clean water / while the hotel filled its pool.','scandal.s2 指对某事在道德上错误的强烈愤慨。','资源分配不公引起愤慨。')],M('The bribery scandal was a routine honest payment that investigators fully approved and never questioned.','The bribery scandal involved secret payments that investigators exposed.','公开且合规的付款不构成贿赂丑闻。','meaning'),[q('Why did the mayor resign?','investigators published records of bribery payments','the clinic had clean water','the scanner copied a page','贿赂付款记录曝光后，市长被迫辞职。',1,'context'),q('What made the situation a scandal to residents?','the clinic lacked water while the hotel filled a pool','the hotel closed its pool','the mayor scanned a noticeboard','诊所缺水而酒店每日注水令居民愤慨。',2,'context'),q('What is a scandal?','a shocking or dishonest event','a medical imaging test','a scale of musical notes','scandal 指令人震惊或不诚实的事件。',1,'meaning'),q('What does “it was a scandal that...” express?','strong indignation that something is morally wrong','a list of routine rules','a slow, light movement','此处 scandal 表达对不公之事的强烈愤慨。',2,'meaning')]);
P('scanner','Scanner is formed from scan and -er; it is a machine that copies images or documents by moving light over them.',C('scanner.s1','扫描仪；扫描器','The office scanner captured both sides of the signed contract and stored the pages as a searchable file.','办公室扫描仪扫描了签署合同的正反两面，并将页面保存为可搜索文件。','The office scanner captured both sides / and stored the pages / as a searchable file.','scanner 指通过光线读取并复制图像或文档的机器。','扫描仪生成可搜索的数字文件。'),M('The office scanner stored the contract by weighing it on a kitchen scale and producing no digital image.','The office scanner copied the contract pages into a searchable digital file.','称重不会扫描或生成文档副本。','meaning'),[q('What did the office scanner capture?','both sides of the signed contract','the patient’s knee','the scale of the project','扫描仪复制了签署合同的正反面。',1,'context'),q('What type of file did it create?','a searchable digital file','a paper scale','a surgical blade','办公室扫描仪把合同页保存为可搜索文件。',1,'context'),q('What is a scanner?','a machine that copies images or documents','a tool that weighs a parcel','a knife used in surgery','scanner 是用来复制图像或文件的机器。',1,'meaning'),q('How does the scanner read the document?','by moving light over it','by climbing a cliff','by burning the paper','扫描仪通过光线扫描文档。',1,'meaning')]);
P('scant','Scant comes from Old Norse skamt, “short”; as an adjective it means barely enough, and as a verb it means give too little or deliberately limit.',[C('scant.s1','不足的；勉强够的','The team had scant evidence, so it delayed its conclusion until more witnesses could be interviewed.','团队掌握的证据不足，因此推迟结论，等待采访更多证人。','The team had scant evidence / so it delayed / its conclusion.','scant.s1 指数量或规模勉强够不上所需程度。','证据太少，无法下结论。'),C('scant.s2','克扣；限制','The landlord scanted the repairs by replacing only one of the three broken stair lights.','房东只更换了三盏坏掉楼梯灯中的一盏，克扣了维修。','The landlord scanted the repairs / by replacing only one / of three broken lights.','scant.s2 作动词，指故意少给或有意限制。','房东只修了一部分。')],M('The team had scant evidence because it possessed every witness statement and multiple clear recordings.','The team had scant evidence because only one uncertain witness statement was available.','掌握大量清晰证据不叫证据不足。','meaning'),[q('Why did the team delay its conclusion?','it had too little evidence','it had interviewed every witness','the repairs were already complete','团队证据不足，因此推迟结论。',1,'context'),q('How did the landlord scant the repairs?','replaced only one of three broken lights','replaced all three lights immediately','scanned each light into a file','房东只更换一盏坏灯，克扣了维修。',2,'context'),q('What does scant mean as an adjective?','barely enough in amount','very large in scale','richly decorated','scant evidence 指数量不足的证据。',1,'meaning'),q('What does scant mean as a verb?','give too little or deliberately limit','provide more than enough','look over quickly','scant 作动词指少给或限制。',2,'meaning')]);
P('scanty','Scanty is formed from scant and -y; it describes an amount too small to be enough or clothing that is thin or covers very little.',[C('scanty.s1','稀少的；不足的','The village had scanty rainfall that year, leaving its reservoir low by the end of summer.','那年村里降雨稀少，夏末水库水位很低。','The village had scanty rainfall / leaving the reservoir / low by summer’s end.','scanty.s1 指数量过少、不足以满足需要。','降雨量太少导致水库水位低。'),C('scanty.s2','单薄的；覆盖很少的','The dancer wore a scanty costume that left her shoulders and much of her back uncovered.','舞者穿着一套露出肩部和大半个背部的单薄服装。','The dancer wore a scanty costume / leaving her shoulders / and back uncovered.','scanty.s2 可指衣服薄或遮盖身体很少。','服装覆盖范围较少。')],M('The village had scanty rainfall because rain fell every day and filled the reservoir to overflowing.','The village had scanty rainfall because very little rain fell and the reservoir stayed low.','每天降雨并使水库溢满，不符合降雨稀少。','meaning'),[q('What was the effect of scanty rainfall?','the reservoir stayed low','the reservoir overflowed','the village had a royal scandal','降雨稀少使水库水位偏低。',1,'context'),q('What did the scanty costume leave uncovered?','the dancer’s shoulders and much of her back','the dancer’s entire body completely','the village reservoir','舞者的单薄服装露出肩部和大半个背部。',2,'context'),q('What does scanty mean about rainfall?','too little to be enough','heavy and continuous','approximately measured','scanty rainfall 指降雨量稀少不足。',1,'meaning'),q('What does scanty mean about clothing?','thin or covering very little','a large amount of cloth','made of surgical steel','scanty costume 指单薄且覆盖较少的服装。',2,'meaning')]);
P('scapegoat','Scapegoat was coined in English by William Tyndale for the biblical goat sent away carrying the community’s sins; today it means a person blamed for others’ wrongdoing.',C('scapegoat.s1','替罪羊','The director made the new assistant a scapegoat for the budget errors, although senior managers had approved every purchase.','尽管所有采购都由高层批准，主管还是把预算错误归咎于新助理。','The director made the assistant a scapegoat / although managers / had approved each purchase.','scapegoat 指代替他人承担责任或被归咎的人。','新助理被不公正地怪罪。'),M('The director made the assistant a scapegoat by blaming her for errors she alone had caused and for which no one else was responsible.','The director made the assistant a scapegoat by blaming her for errors approved by senior managers.','若错误确由助理独自造成，就不是替他人背锅。','meaning'),[q('Who approved the purchases that caused the budget errors?','senior managers','the new assistant alone','the biblical goat','高层批准采购，却把错误归咎于新助理。',1,'context'),q('What does scapegoat mean?','a person unfairly blamed for others’ mistakes','a person who approves every purchase','a medical scanner','scapegoat 指被用来替他人承担责备的人。',1,'meaning'),q('Why was the assistant an unfair scapegoat?','managers had approved the purchases','she alone had made every error','she refused to scan a document','预算错误涉及高层批准，不应只怪罪新助理。',1,'context'),q('What story helped form the word scapegoat?','a biblical goat sent away carrying the community’s sins','a goat that climbed a mountain','a ruler weighing a parcel','scapegoat 源于圣经中带走群体罪责的替罪羊。',1,'word-formation')]);
P('scar','Scar may come through Old French escarre from Greek eskhara, “scab”; it can name a healed skin mark or lasting harm, or mean leave such a mark.',[C('scar.s1','伤疤；疤痕','A thin scar remained on Jo’s palm after the kitchen burn had healed.','厨房烫伤愈合后，乔的手掌上留下一道细疤。','A thin scar remained / on Jo’s palm / after the burn healed.','scar.s1 指伤口愈合后留在皮肤上的痕迹。','烫伤愈合后留下疤痕。'),C('scar.s2','精神创伤；持久损害','Years of displacement scarred the community, whose families still feared another forced move.','多年的流离失所给社区留下创伤，许多家庭至今仍害怕再次被迫迁离。','Years of displacement scarred the community / whose families / feared another move.','scar.s2 指对心灵或地方造成的长期不良影响。','长期迁徙给社区留下创伤。'),C('scar.s3','使留下伤疤；创伤','The acid spill scarred the stone steps permanently, leaving pale lines across the dark surface.','酸液泄漏永久损坏了石阶，在深色表面留下浅色痕迹。','The acid spill scarred the steps / leaving pale lines / across the surface.','scar.s3 作动词，指在皮肤或情感上留下永久痕迹。','酸液在石阶上留下痕迹。')],M('The burn left no scar on Jo’s palm because the skin remained completely unchanged after healing.','The burn left a thin scar on Jo’s palm after the skin healed.','皮肤完全没有痕迹就没有留下疤痕。','meaning'),[q('Where did Jo’s scar remain?','on her palm','on the noticeboard','on the map scale','烫伤愈合后，乔的手掌上留下一道细疤。',1,'context'),q('What did years of displacement do to the community?','left lasting emotional harm','made its stone steps smooth','provided scanty rainfall','多年流离失所给社区留下长期创伤。',2,'context'),q('What did the acid spill do to the steps?','left permanent pale lines','healed the stone completely','scanned the surface into an image','酸液在石阶上留下永久浅色痕迹。',3,'context'),q('Which use of scar means a mark left after healing?','a thin scar remained on her palm','displacement scarred the community','acid scarred the stone steps','第一句中的 scar 是愈合后皮肤上的疤痕。',1,'meaning')]);
P('scarce','Scarce came through Old French escars, “scanty,” with deeper history uncertain; it means insufficient in quantity or rare and hard to obtain.',[C('scarce.s1','缺乏的；不足的','Clean drinking water became scarce after the pipes froze during the week-long cold spell.','持续一周的寒潮冻坏管道后，干净饮用水变得不足。','Clean drinking water became scarce / after pipes froze / during the cold spell.','scarce.s1 指现有数量不足以满足需要。','管道结冰导致饮用水不足。'),C('scarce.s2','稀少的；难得一见的','The small island is home to a scarce bird that nests only on two cliffs in the region.','这座小岛上生活着一种稀有鸟类，它只在该地区两处峭壁筑巢。','The island is home to a scarce bird / that nests / on only two cliffs.','scarce.s2 指稀少、难以找到或获得的。','这种鸟只在两处峭壁筑巢。')],M('Clean drinking water was scarce even though the frozen pipes supplied more than the town could store.','Clean drinking water was scarce because frozen pipes sharply reduced the available supply.','供水超过储存能力时，不是水源不足。','meaning'),[q('Why did clean water become scarce?','the pipes froze during the cold spell','the island had too many nesting cliffs','the scanner copied a page','寒潮冻坏管道后，可用饮用水减少。',1,'context'),q('Where does the scarce bird nest?','on only two cliffs in the region','in every town’s garden','inside the frozen pipes','这种稀有鸟类只在该地区两处峭壁筑巢。',2,'context'),q('What does scarce mean about water?','not available in sufficient quantity','easy to obtain everywhere','painful after a burn','scarce water 指数量不足的水。',1,'meaning'),q('What does scarce mean about the bird?','rare and hard to find','in large numbers on every cliff','covered with scales','scarce bird 指稀少难见的鸟。',2,'meaning')]);
P('scarcely','Scarcely combines scarce and -ly; it means hardly or almost not at all, and in “scarcely had...when” it means one event followed immediately by another.',[C('scarcely.s1','几乎不；简直没有','There was scarcely enough light to read the map, so the hikers waited until dawn.','光线几乎不足以看地图，因此徒步者等到天亮。','There was scarcely enough light / to read the map / so they waited.','scarcely.s1 表示几乎没有或几乎不能。','天色太暗，几乎看不清地图。'),C('scarcely.s2','刚一……就……','Scarcely had the train left the station when the conductor noticed a suitcase under the empty seat.','火车刚离开车站，列车员就注意到空座位下有一个手提箱。','Scarcely had the train left / when the conductor noticed / the suitcase.','scarcely.s2 与 when 连用，表示一件事刚发生另一件就发生。','列车刚出发列车员便发现行李。')],M('There was scarcely enough light to read because the hikers could see every map detail perfectly.','There was scarcely enough light to read because the map was nearly impossible to see.','能够清楚看见所有细节与光线几乎不足相矛盾。','meaning'),[q('Why did the hikers wait until dawn?','there was hardly enough light to read the map','the train had just left','the island bird was common','徒步者几乎看不清地图，所以等到天亮。',1,'context'),q('What happened just after the train left?','the conductor noticed a suitcase','the hikers reached the summit','the pipes froze','列车刚开出，列车员就发现座位下的手提箱。',2,'context'),q('What does scarcely mean in the map example?','almost not at all','very easily','immediately after','这里 scarcely 表示几乎没有足够光线。',1,'meaning'),q('How does “scarcely...when” connect events?','the second event follows almost immediately','the second event never happens','both events occur years apart','scarcely...when 表示一件事刚发生，另一件事紧接着发生。',2,'meaning')]);
P('scarcely any','Scarcely any means very few or very little of something; it combines scarcely (“almost not”) with any.',C('scarcely any.s1','几乎没有','There was scarcely any milk left in the refrigerator, so I added water to the pancake batter.','冰箱里几乎没有牛奶了，所以我在煎饼面糊里加了些水。','There was scarcely any milk left / so I added water / to the batter.','scarcely any 用于表示数量极少或几乎没有。','剩余牛奶很少，不够做面糊。'),M('There was scarcely any milk left even though the refrigerator was full of unopened cartons.','There was scarcely any milk left because only a few drops remained.','冰箱里装满未开封牛奶，不符合几乎没有的意思。','meaning'),[q('What was scarcely left in the refrigerator?','milk','pancake batter','clean water','冰箱里几乎没有牛奶了。',1,'context'),q('What did the speaker add to the batter?','water','more milk from many full cartons','a scale','说话者因牛奶不足而加水。',1,'context'),q('What does scarcely any mean?','very little or almost none','an exact large quantity','one event immediately after another','scarcely any 指数量极少、几乎没有。',1,'meaning'),q('Which situation has scarcely any?','a jar with only a few drops of honey','a cupboard packed with jars','a glass filled to the rim','只剩几滴蜂蜜的罐子里 scarcely any honey。',1,'context')]);
P('scarcity','Scarcity is formed from scarce and -ity; it means a lack of something needed, or in economics the condition that resources are limited while wants are not.',[C('scarcity.s1','缺乏；不足','The scarcity of nurses forced the clinic to shorten its evening hours during the winter.','护士短缺迫使诊所在冬季缩短晚间营业时间。','The scarcity of nurses forced the clinic / to shorten / its evening hours.','scarcity.s1 指人们需要的东西缺乏。','护士不足影响诊所服务时间。'),C('scarcity.s2','稀缺（经济学）','The lesson used water scarcity to explain why limited resources must be allocated among competing needs.','课程用水资源稀缺说明为什么必须在相互竞争的需求之间分配有限资源。','The lesson used water scarcity / to explain allocation / of limited resources.','scarcity.s2 指资源有限而需求或欲望没有上限的经济状态。','有限水资源需要分配。')],M('The scarcity of nurses forced the clinic to extend its hours because it had more nurses than it could schedule.','The scarcity of nurses forced the clinic to shorten hours because too few nurses were available.','护士过剩不会造成护士短缺。','meaning'),[q('Why did the clinic shorten evening hours?','too few nurses were available','the water resources were unlimited','the clinic had a new scanner','护士短缺迫使诊所缩短晚间服务。',1,'context'),q('What concept did the lesson use to discuss allocating limited resources?','water scarcity','a scarce musical scale','a medical scan','课程用水资源稀缺讲解有限资源分配。',2,'context'),q('What is scarcity?','a lack of something people need','a large supply of everything','a medical image of the body','scarcity 指人们所需事物的缺乏。',1,'meaning'),q('What does scarcity mean in economics?','resources are limited while wants are not','all resources exceed every possible want','a shortage caused only by a broken pipe','经济学中的 scarcity 指资源有限而需求无穷。',2,'meaning')]);
P('scare','Scare has uncertain deeper origins; it can mean frighten someone or name a sudden feeling of fear shared by many people.',[C('scare.s1','惊吓；使害怕','The sudden bark scared the cyclist, who stopped and checked that the dog was behind a fence.','突然的狗叫吓到了骑车人，他停下来确认狗在围栏后面。','The sudden bark scared the cyclist / who stopped / to check the fence.','scare.s1 作动词，指使人或动物感到害怕。','突如其来的狗叫吓到骑车人。'),C('scare.s2','惊恐；恐慌','A food-safety scare began when several customers reported finding glass in packaged soup.','几位顾客报告在包装汤里发现玻璃后，食品安全恐慌开始蔓延。','A food-safety scare began / after customers reported / glass in the soup.','scare.s2 作名词，指许多人突然共同感到的恐慌。','食品中有玻璃的报告引发恐慌。')],M('The dog’s bark scared the cyclist by making him feel completely calm and unafraid.','The dog’s sudden bark scared the cyclist and made him stop in alarm.','完全平静、不害怕与被惊吓相反。','meaning'),[q('What caused the cyclist to stop?','a sudden bark behind a fence','a shortage of nurses','a clear scan of the knee','狗突然叫了一声，吓得骑车人停下来。',1,'context'),q('What started the food-safety scare?','reports of glass in packaged soup','the clinic shortened its hours','the train left the station','包装汤中发现玻璃的报告引发了食品安全恐慌。',2,'context'),q('What does scare mean as a verb?','make someone feel afraid','a sudden public feeling of fear','a lack of something needed','动词 scare 指使人感到害怕。',1,'meaning'),q('What does scare mean as a noun in “a food-safety scare”?','a sudden shared feeling of fear','a single person’s act of frightening someone','a medical scan','此处 scare 指多人因食品安全消息产生的恐慌。',2,'meaning')]);
P('scared','Scared is the past participle of scare; it describes someone feeling fear or being afraid.',C('scared.s1','害怕的','The scared child held her father’s hand while the storm rattled the windows.','暴风雨震得窗户作响时，害怕的孩子紧紧握着父亲的手。','The scared child held her father’s hand / while the storm / rattled the windows.','scared 描写感到恐惧的人。','孩子因风暴声响而害怕。'),M('The scared child laughed confidently at the storm and showed no fear or need for comfort.','The scared child held her father’s hand because the storm frightened her.','毫无恐惧且自信大笑不符合 scared。','meaning'),[q('What did the scared child hold?','her father’s hand','a measuring scale','a scalpel','害怕的孩子在暴风雨中握着父亲的手。',1,'context'),q('What made the child feel scared?','the storm rattling the windows','the C-major scale','a scarf around her neck','暴风雨震响窗户，让孩子感到害怕。',1,'context'),q('What does scared mean?','feeling fear','making someone else afraid','very scarce in quantity','scared 指感到害怕。',1,'meaning'),q('Which person is scared?','someone who grips a parent’s hand during a frightening storm','someone who calmly watches a familiar rain shower','someone who scares a cyclist with a bark','在令人害怕的暴风雨中握紧家长的孩子是 scared。',1,'context')]);
P('scarf','Scarf as neckwear is recorded in Middle English, but its deeper origin is uncertain; it names a long cloth worn around the neck or a square cloth worn on the head/neck.',[C('scarf.s1','围巾','Mina wrapped a wool scarf around her neck before walking to the bus stop in the freezing wind.','米娜在寒风中步行去公交站前，把羊毛围巾绕在脖子上。','Mina wrapped a wool scarf around her neck / before walking / in the freezing wind.','scarf.s1 指围在脖子上保暖的长布条。','羊毛围巾挡住冷风。'),C('scarf.s2','头巾；领巾','At the outdoor ceremony, the dancer tied a square scarf over her hair and secured it beneath her chin.','户外典礼上，舞者把一条方巾盖在头发上，并在下巴下系好。','The dancer tied a square scarf over her hair / securing it / beneath her chin.','scarf.s2 指覆盖头部或系在颈部的方形布。','舞者用方巾遮住头发。')],M('Mina wore a scarf around her neck in the freezing wind by wrapping a thin sheet of ice around her throat.','Mina wore a wool scarf around her neck to keep warm in the freezing wind.','冰片不能作为围巾保暖，且会使人受冻。','meaning'),[q('What kind of scarf did Mina wear?','a wool scarf','a square headscarf','a medical scan','米娜在寒风中围了一条羊毛围巾。',1,'context'),q('How did the dancer wear her square scarf?','over her hair and tied beneath her chin','around her neck under a winter coat','over the noticeboard','舞者把方巾盖在头上并在下巴下系好。',2,'context'),q('What does scarf mean in Mina’s sentence?','a long cloth worn around the neck for warmth','a square cloth worn over the head','a small hard plate on a fish','米娜句中的 scarf 指围在脖子上保暖的围巾。',1,'meaning'),q('What does scarf mean in the ceremony example?','a square cloth worn over the head','a wool neck warmer only','a mark left after a cut','典礼句中的 scarf 指盖在头上的方巾。',2,'meaning')]);
P('scarlet','Scarlet came through Old French escarlate; its deeper origin is uncertain. It describes a bright, vivid red color.',C('scarlet.s1','猩红色的；鲜红色的','The fire crew wore scarlet jackets so drivers could see them through the smoke.','消防队员穿着鲜红色夹克，让司机能透过烟雾看见他们。','The fire crew wore scarlet jackets / so drivers / could see them through smoke.','scarlet 指明亮鲜艳的红色。','鲜红色衣服提高能见度。'),M('The crew wore scarlet jackets that were pale blue and nearly invisible in the smoke.','The crew wore scarlet jackets in a vivid bright-red color.','淡蓝色不是 scarlet 的鲜红色。','meaning'),[q('What color were the fire crew’s jackets?','bright red','pale blue','dark green','消防队员穿着鲜红色夹克。',1,'context'),q('Why did the crew wear scarlet?','drivers could see them through smoke','the jackets gave off no scent','they were scheduled to wear blue','鲜红色使消防队员在烟雾中更显眼。',1,'context'),q('What does scarlet mean?','a vivid bright red','a dark shade of green','a pale yellow','scarlet 指鲜艳的猩红色。',1,'meaning'),q('Which item is scarlet?','a bright red flag','a blue-gray stone','a scentless bottle','鲜红色旗帜可以称为 scarlet。',1,'context')]);
P('scat','Scat has separate uses: jazz scat names improvised singing with nonsense syllables; the command “scat!” has uncertain origin and tells someone or an animal to leave.',[C('scat.s1','拟声唱法','The vocalist used scat, improvising “ba-doo-bop” sounds between the trumpet solos.','歌手在小号独奏之间用“ba-doo-bop”等无意义音节即兴演唱。','The vocalist used scat / improvising nonsense syllables / between trumpet solos.','scat.s1 指爵士乐中用无意义音节即兴演唱。','歌手即兴唱出非词语音节。'),C('scat.s2','快走；走开','The farmer shouted “Scat!” when the fox approached the henhouse.','狐狸靠近鸡舍时，农夫大喊“走开！”。','The farmer shouted “Scat!” / when the fox / approached the henhouse.','scat.s2 作命令，叫人或动物离开。','农夫用命令赶走狐狸。')],M('The singer performed scat by reciting a carefully written poem with every word planned in advance.','The singer performed scat by improvising playful nonsense syllables.','逐字背诵预先写好的诗不是即兴拟声唱法。','meaning'),[q('What did the vocalist improvise between trumpet solos?','nonsense syllables','a written film outline','a command for the fox to leave','歌手在小号独奏之间即兴唱无意义音节。',1,'context'),q('Why did the farmer shout “Scat!”?','a fox was approaching the henhouse','the jazz solo had ended','the scheduled train arrived','农夫喊“走开”是要赶走靠近鸡舍的狐狸。',2,'context'),q('What is scat in jazz?','improvised singing with nonsense syllables','a written musical score','a loud public argument','爵士乐中的 scat 是用无意义音节即兴演唱。',1,'meaning'),q('What does the command “Scat!” tell an animal to do?','leave','sing a jazz solo','approach the henhouse','“Scat!” 是叫动物离开的命令。',2,'meaning')]);
P('scathe','Scathe comes from Old Norse skaða, “harm”; it can name injury or destruction, or mean attack someone with severe criticism.',[C('scathe.s1','损伤；伤害','The hail caused little scathe to the greenhouse because its panels were reinforced.','由于温室面板经过加固，冰雹只造成了轻微损伤。','The hail caused little scathe / because the greenhouse panels / were reinforced.','scathe.s1 作名词，指伤害、损伤或破坏。','加固玻璃减轻了损伤。'),C('scathe.s2','痛斥；猛烈批评','The columnist scathed the proposal for ignoring the cost of repairs to the flooded homes.','专栏作者痛斥这项提案忽略了洪水受损房屋的维修费用。','The columnist scathed the proposal / for ignoring repair costs / to flooded homes.','scathe.s2 作动词，指严厉批评某人或某事。','作者猛烈批评提案。')],M('The hail caused scathe to the greenhouse by leaving every panel intact and undamaged.','The hail caused scathe by cracking several greenhouse panels.','面板完好无损就没有造成损伤。','meaning'),[q('Why was damage to the greenhouse limited?','its panels were reinforced','the columnist praised the proposal','the roof was made of scenery','加固面板减少了冰雹造成的损伤。',1,'context'),q('What did the columnist scathe?','the proposal that ignored repair costs','the reinforced greenhouse panels','the jazz singer’s nonsense syllables','专栏作者痛斥忽略灾后维修费用的提案。',2,'context'),q('What does scathe mean as a noun?','harm or destruction','severe public criticism','a written schedule','scathe 作名词指损伤或破坏。',1,'meaning'),q('What does scathe mean as a verb?','attack with severe criticism','cover with scarlet fabric','plan an event at a fixed time','动词 scathe 指严厉批评。',2,'meaning')]);
P('scatter','Scatter is recorded in Middle English for dispersing things; its deeper origin is uncertain. It can mean spread objects over an area or move a group in different directions.',[C('scatter.s1','撒；散布','The gardener scattered grass seed over the bare patch and then watered it lightly.','园丁把草籽撒在裸露的地面上，然后轻轻浇水。','The gardener scattered seed / over the bare patch / and watered it.','scatter.s1 指把物品抛撒或散布到一大片区域。','草籽被撒在空地上。'),C('scatter.s2','散开；驱散','When the bell rang, the students scattered in different directions across the playground.','铃声响起后，学生们朝操场各处散开。','The students scattered / in different directions / when the bell rang.','scatter.s2 指人群或动物向不同方向散开，也可指使其散开。','学生听到铃声后散开。')],M('The gardener scattered seed by keeping every seed in one closed bag and planting none on the ground.','The gardener scattered seed by spreading it across the bare patch.','种子留在袋中、没有撒出，不符合散布的意思。','meaning'),[q('Where did the gardener scatter the grass seed?','over the bare patch','inside the seed bag','across the theater stage','园丁把草籽撒在裸露地面上。',1,'context'),q('What did the students do when the bell rang?','moved in different directions','formed one fixed line and stayed still','scanned the scenery','学生听到铃声后朝不同方向散开。',2,'context'),q('What does scatter mean in the gardening example?','throw or spread things over an area','run away from a frightening dog','make a loud angry argument','园艺语境中的 scatter 指把种子撒开。',1,'meaning'),q('What does scatter mean in the playground example?','move apart in different directions','spread seed over bare ground','schedule a school event','学生 scatter 指四散开来。',2,'meaning')]);
P('scattered','Scattered is the past participle of scatter; it describes things spread over a wide area with spaces between them.',C('scattered.s1','分散的；散落的','Scattered cottages dotted the hillside, with long stretches of forest between each small group.','山坡上散落着几处村舍，各小群之间隔着大片森林。','Scattered cottages dotted the hillside / with forest / between each group.','scattered 描写物体分布广、彼此间隔较远。','村舍零星分布在山坡上。'),M('The cottages were scattered across the hillside even though they stood wall to wall in one dense row.','The cottages were scattered across the hillside with forest separating small groups.','紧挨着排成一行不是分散分布。','meaning'),[q('What separated groups of cottages?','long stretches of forest','a theater stage','a scheduled school bus','大片森林隔开了山坡上的村舍群。',1,'context'),q('How were the cottages arranged?','in separated groups across the hillside','wall to wall in one row','inside a single theater room','村舍分散在山坡上，并非密集排在一起。',1,'context'),q('What does scattered mean?','spread over an area with spaces between','gathered tightly in one spot','planned for a particular time','scattered 指分布在不同位置、彼此有间隔。',1,'meaning'),q('Which arrangement is scattered?','several cabins separated by woods','houses sharing walls along one street','one cabin in a crowded city block','被树林隔开的几处小屋是 scattered。',1,'context')]);
P('scattering','Scattering is formed from scatter and -ing; it means a small number of things spread thinly over an area.',C('scattering.s1','零星散布；少量','A scattering of wildflowers appeared among the rocks, though most of the hillside remained bare.','岩石间零星长着几朵野花，山坡大部分地方仍然裸露。','A scattering of wildflowers appeared / among the rocks / while most ground stayed bare.','scattering 可指稀疏分布的一小部分事物。','野花数量少且分布稀疏。'),M('A scattering of wildflowers covered the entire hillside densely, leaving no bare ground anywhere.','A scattering of wildflowers appeared in a few places among otherwise bare rocks.','密密麻麻覆盖整片山坡不属于零星少量。','meaning'),[q('Where did the scattering of wildflowers appear?','among the rocks','inside the theater','along every city street','野花只在岩石间零星出现。',1,'context'),q('Was most of the hillside covered with flowers?','no, most of it remained bare','yes, every part was densely covered','only the forest was covered','山坡大部分仍然裸露，只有少量野花。',1,'context'),q('What does a scattering of things mean?','a small number spread thinly over an area','a large crowd gathered in one place','a fixed list of scheduled events','a scattering 指零星分布的一小部分事物。',1,'meaning'),q('Which scene shows a scattering of objects?','a few shells spaced along a long beach','a solid pile of shells filling one box','a row of shells placed edge to edge','海滩上间隔放着几枚贝壳，属于 scattering。',1,'context')]);
P('scavenge','Scavenge developed from scavenger, a person who removed refuse; it means search for decaying food or look through waste and abandoned places for useful things.',[C('scavenge.s1','（动物）觅食腐物','Vultures scavenge for dead animals on the dry plain when fresh prey is scarce.','新鲜猎物稀少时，秃鹫会在干燥平原上觅食动物尸体。','Vultures scavenge for dead animals / on the dry plain / when prey is scarce.','scavenge.s1 指动物寻找并吃掉其他动物留下的腐肉。','秃鹫以动物尸体为食。'),C('scavenge.s2','翻找有用之物','The repair crew scavenged useful boards from the abandoned shed for the temporary stage.','维修队从废弃棚屋里翻找有用木板，搭建临时舞台。','The crew scavenged useful boards / from the abandoned shed / for the stage.','scavenge.s2 指从垃圾或废弃处翻找可用物品。','木板被从废弃棚屋里找出再利用。')],M('The vultures scavenged for dead animals by hunting only fresh prey and avoiding every carcass.','The vultures scavenged for dead animals by feeding on carcasses left on the plain.','只捕杀新鲜猎物并避开尸体，不符合觅食腐肉。','meaning'),[q('What did the vultures search for?','dead animals on the plain','useful boards in a shed','a missing script page','秃鹫在平原上觅食动物尸体。',1,'context'),q('Where did the repair crew find boards?','in an abandoned shed','on the dry plain','in the orchestra pit','维修队从废弃棚屋里翻找木板。',2,'context'),q('What does scavenge mean for vultures?','search for and feed on dead animals','repair a stage with new wood','scan an image into a file','秃鹫 scavenge 指觅食其他动物留下的腐肉。',1,'meaning'),q('What does scavenge mean in the repair-crew example?','look through an abandoned place for useful things','eat decaying food as an animal','write an outline for a film','维修队 scavenge 指翻找可再利用的木板。',2,'meaning')]);
P('scavenger','Scavenger developed from Middle English scawager, originally a municipal refuse collector; it can mean a carrion-eating animal or a person who collects discarded goods.',[C('scavenger.s1','食腐动物','A scavenger such as a vulture helps remove carcasses from the grassland ecosystem.','秃鹫这样的食腐动物有助于清除草原生态系统中的动物尸体。','A scavenger such as a vulture / helps remove carcasses / from the grassland.','scavenger.s1 指以其他动物留下的尸体为食的动物。','秃鹫清理草原尸体。'),C('scavenger.s2','拾荒者；清扫的人','The scavenger collected discarded metal from the demolition site and sold it for recycling.','拾荒者从拆迁现场收集废弃金属，卖去回收利用。','The scavenger collected discarded metal / from the demolition site / for recycling.','scavenger.s2 指收集废弃物以再利用或出售的人。','废弃金属被收集后回收。')],M('The scavenger helped the grassland by refusing to feed on any carcass or remove any dead material.','The scavenger helped the grassland by feeding on carcasses and clearing dead material.','不清理尸体与食腐动物的生态作用相反。','meaning'),[q('How does a vulture scavenger help the grassland?','removes carcasses','collects metal from a demolition site','writes the theater schedule','秃鹫通过清除动物尸体帮助草原生态系统。',1,'context'),q('What did the human scavenger collect?','discarded metal','wildflowers','film scenery','拾荒者从拆迁现场收集废弃金属。',2,'context'),q('What is a scavenger animal?','an animal that feeds on dead matter','an animal that eats only fresh plants','a machine that scans documents','scavenger 动物指以尸体为食的动物。',1,'meaning'),q('What is a scavenger person?','someone who collects discarded things to reuse or sell','someone who writes a film outline','someone who takes medical scans','scavenger 人指收集废弃物再利用或出售的人。',2,'meaning')]);
P('scenario','Scenario comes from Italian scenario, “stage outline,” from scena (“scene”); it can mean a possible way a situation may develop or a written outline for a film/play.',[C('scenario.s1','可能出现的情况；设想','The emergency scenario assumes that the bridge closes just as the evening buses arrive.','应急设想假定桥梁在晚间公交抵达时关闭。','The emergency scenario assumes / the bridge closes / as buses arrive.','scenario.s1 指对某种情况如何发展的描述或假设。','应急方案设想桥梁关闭。'),C('scenario.s2','（电影）剧本提纲；情节梗概','The producer approved a short scenario outlining the film’s opening, central conflict, and final escape.','制片人批准了一份简短剧本提纲，概述电影开场、核心冲突和最终逃脱。','The producer approved a scenario / outlining the opening / conflict, and escape.','scenario.s2 指电影或戏剧情节的书面提纲。','提纲概括电影主要情节。')],M('The emergency scenario was a confirmed account of yesterday’s bridge closure, not a description of a possible event.','The emergency scenario described what could happen if the bridge closed when buses arrived.','已经确认的历史记录不是可能情境的设想。','meaning'),[q('What does the emergency scenario assume?','the bridge closes as evening buses arrive','the film ends with an opening scene','the bridge is permanently open','应急设想考虑桥梁关闭与公交抵达同时发生。',1,'context'),q('What did the film scenario outline?','the opening, conflict, and final escape','the bridge timetable only','wildflowers on a hillside','剧本提纲概述开场、冲突和结局。',2,'context'),q('What is a scenario in emergency planning?','a description of how a situation might develop','a finished historical report only','a painted background on a stage','应急 scenario 指对可能情境发展的设想。',1,'meaning'),q('What is a scenario in film production?','a written outline of the action','a full camera scan','a review of the scenery','电影 scenario 指书面情节提纲。',2,'meaning')]);
P('scene','Scene comes through French scène from Latin scena and Greek skēnē, “tent or stage”; it can mean an event’s location/situation, a view, a part of a play/film, or a public angry display.',[C('scene.s1','场面；情景；现场','Police secured the scene of the collision while paramedics treated the injured cyclists nearby.','警察封锁了碰撞现场，同时医护人员在附近救治受伤的骑行者。','Police secured the scene / while paramedics treated / the injured cyclists.','scene.s1 指事件发生的地点及其现场状况。','事故现场被封锁。'),C('scene.s2','景色；景象','From the overlook, we admired the scene of snow-covered hills reflected in the lake.','从观景台望去，我们欣赏着白雪覆盖的山丘倒映在湖中的景色。','We admired the scene / of snow-covered hills / reflected in the lake.','scene.s2 指可以观看到的景象或风景。','湖面映出山丘景色。'),C('scene.s3','（戏剧、电影的）一场','The final scene of the play takes place in a railway station just before dawn.','这部戏的最后一场发生在黎明前的火车站。','The final scene of the play / takes place / at a railway station.','scene.s3 指戏剧或电影中发生在一个地点的一部分。','最后一场设置在车站。'),C('scene.s4','当众吵闹；发脾气','The customer made a scene in the restaurant when the server explained that the kitchen was closed.','服务员解释厨房已关门后，顾客在餐厅里大吵大闹。','The customer made a scene / when the server explained / the kitchen was closed.','scene.s4 常用于 make a scene，指在公共场合大声争吵或发脾气。','顾客当众吵闹。')],M('Police secured the scene of the collision by letting traffic pass through it and removing no evidence.','Police secured the scene by closing the area while paramedics treated the injured.','让车辆穿过且不保护现场与封锁事故现场相反。','meaning'),[q('What did police secure?','the place where the collision happened','the lake view from the overlook','the final play sequence','警察封锁了碰撞事故现场。',1,'context'),q('What did visitors admire from the overlook?','snow-covered hills reflected in a lake','a collision scene','an angry customer','观景台上看到雪山倒映在湖中的景色。',2,'context'),q('Where does the play’s final scene take place?','at a railway station','at the collision site','in a restaurant kitchen','戏剧最后一场发生在火车站。',3,'context'),q('What did the customer do when told the kitchen was closed?','made a loud public argument','admired the snowy scene','secured the accident site','顾客当众大吵大闹，made a scene。',4,'context')]);
P('scenery','Scenery is formed from scene and -ery; it can mean the natural features of a place or painted backgrounds used on a stage.',[C('scenery.s1','风景；自然景色','The train window framed the coastal scenery, with cliffs, beaches, and pine-covered slopes.','火车窗框住了海岸风景，可以看到悬崖、海滩和松树覆盖的山坡。','The train window framed the coastal scenery / with cliffs / and pine-covered slopes.','scenery.s1 指某地的自然景物。','沿途可见海岸自然景色。'),C('scenery.s2','舞台布景','The crew changed the scenery between acts, replacing the painted forest with a city street.','工作人员在幕间更换布景，把彩绘森林换成城市街道。','The crew changed the scenery / between acts / from forest to street.','scenery.s2 指戏台上绘制或搭建的背景。','换幕时更换舞台背景。')],M('The train passed coastal scenery that consisted only of blank walls and no cliffs, beaches, or natural features.','The train passed coastal scenery with cliffs, beaches, and pine-covered slopes.','没有任何自然景物的空白墙面不是海岸风景。','meaning'),[q('What coastal features could passengers see?','cliffs, beaches, and pine-covered slopes','painted city streets between acts','the accident site','乘客看到悬崖、海滩和松林组成的海岸风景。',1,'context'),q('When did the crew change the scenery?','between acts','during the train ride','after the collision','工作人员在幕间更换舞台布景。',2,'context'),q('What does scenery mean in the train example?','natural features of a place','painted background on a stage','a film’s written outline','这里 scenery 指自然风景。',1,'meaning'),q('What does scenery mean in the theater example?','painted or built stage backgrounds','a natural view of hills','an angry scene in public','剧场例子中的 scenery 指舞台布景。',2,'meaning')]);
P('scenic','Scenic is formed from scene and -ic; it describes a place with beautiful natural views, and can also be a noun for a film or photograph showing scenery.',[C('scenic.s1','风景优美的','The scenic road winds above the lake and offers a clear view of the snow-covered peaks.','这条风景优美的公路沿湖蜿蜒，可清晰看见白雪覆盖的山峰。','The scenic road winds above the lake / offering views / of snowy peaks.','scenic.s1 指拥有或展现美丽自然景色的。','道路沿途可观赏雪山和湖泊。'),C('scenic.s2','风景影片；风景照片','The museum screened a scenic of the northern coastline, showing cliffs and quiet fishing villages.','博物馆放映了一部北部海岸风光影片，展现悬崖和宁静的渔村。','The museum screened a scenic / showing cliffs / and fishing villages.','scenic.s2 作名词，指展现优美风景的电影或照片。','放映风景影片展示海岸。')],M('The scenic road was known for its beautiful views even though it ran through a windowless industrial tunnel.','The scenic road offered clear views of the lake and snow-covered peaks.','没有景色可看的封闭隧道不适合称为风景优美的道路。','meaning'),[q('What could travelers see from the scenic road?','the lake and snowy peaks','a painted stage forest only','a crowded collision site','风景公路可以看到湖泊和雪山。',1,'context'),q('What did the museum screen?','a film showing the northern coastline','a schedule for the theater crew','a close-up medical scan','博物馆放映了展现北部海岸的风光影片。',2,'context'),q('What does scenic mean as an adjective?','having or showing beautiful natural views','planned for a certain time','improvised with nonsense syllables','scenic 作形容词指风景优美的。',1,'meaning'),q('What is a scenic as a noun?','a film or photograph showing scenery','a road with an ugly view','a play’s final scene','名词 scenic 指风景影片或风景照片。',2,'meaning')]);
P('scent','Scent comes through Old French from Latin sentire, “perceive”; it can mean a pleasant smell or animal trail, perfume, or discover something by smell/suspicion.',[C('scent.s1','香味；气味','The scent of orange blossoms drifted into the courtyard from the garden after the rain.','雨后，橙花的香气从花园飘进庭院。','The scent of orange blossoms drifted / into the courtyard / after rain.','scent.s1 指令人愉快的气味，也可指动物留下的气味线索。','橙花的香气飘入庭院。'),C('scent.s2','香水','She dabbed a little scent on her wrist before leaving for the evening concert.','她去参加晚间音乐会前，在手腕上抹了一点香水。','She dabbed scent on her wrist / before leaving / for the concert.','scent.s2 指涂在皮肤上的香水液体。','香水被涂在手腕上。'),C('scent.s3','嗅到；察觉','The detective scented a lie when the witness changed his story about the missing bag.','证人改变了关于失踪包的说法，侦探察觉到其中有谎言。','The detective scented a lie / when the witness / changed his story.','scent.s3 作动词，指通过嗅觉发现，或开始怀疑某事。','侦探察觉证词有问题。')],M('The detective scented a lie by accepting the witness’s changing story without any suspicion.','The detective scented a lie when the witness changed his story and raised suspicion.','毫无怀疑地接受说法不符合察觉到谎言。','meaning'),[q('What scent drifted into the courtyard?','orange blossoms','a painted forest','a rubber gasket','雨后橙花的香气飘进庭院。',1,'context'),q('Where did she dab the scent before the concert?','on her wrist','on the noticeboard','on the scenic road','她在参加音乐会前把香水抹在手腕上。',2,'context'),q('What made the detective scent a lie?','the witness changed his story','orange blossoms filled the courtyard','the concert was scheduled','证人改变说法让侦探察觉到谎言。',3,'context'),q('What does scent mean in the flower example?','a pleasant smell','a perfume applied to skin','the act of suspecting a lie','橙花的 scent 指香气。',1,'meaning')]);
P('scented','Scented is formed from scent and -ed; it describes something given a pleasant smell or containing perfume.',C('scented.s1','有香味的；含香料的','The shop wrapped the gift in scented paper that released a faint lavender smell when opened.','商店用有香味的纸包装礼物，打开时会散发淡淡薰衣草气味。','The shop wrapped the gift in scented paper / that released / a lavender smell.','scented 指被赋予香气或含有香料的。','打开包装纸可闻到薰衣草香。'),M('The scented paper gave off no smell at all and contained no perfume or aromatic material.','The scented paper released a faint lavender fragrance when opened.','完全没有气味、也无香料的纸不是 scented。','meaning'),[q('What smell did the paper release?','a faint lavender fragrance','a strong smell of smoke','the scent of orange blossoms only','有香味的包装纸散发淡淡薰衣草香。',1,'context'),q('When could the scent be noticed?','when the paper was opened','when the scenic road closed','before the rain began','礼物打开时会闻到薰衣草香。',1,'context'),q('What does scented mean?','given a pleasant smell or containing perfume','having no smell','covered in scarlet paint','scented 指带有香气或含香料。',1,'meaning'),q('Which object is scented?','a candle made with lavender oil','a scentless sealed stone','a blank film outline','含薰衣草油的蜡烛是 scented。',1,'context')]);
P('scentless','Scentless combines scent and -less; it means giving off no smell.',C('scentless.s1','无气味的','The scentless cleaning solution removed the stain without leaving a fragrance in the small room.','这种无气味清洁剂去掉污渍后，没有在小房间里留下香味。','The scentless solution removed the stain / without leaving / a fragrance.','scentless 指不会散发任何气味的。','清洁后房间没有残留香味。'),M('The scentless solution filled the room with a strong floral perfume.','The scentless solution removed the stain without producing any smell.','散发浓烈花香的液体不是 scentless。','meaning'),[q('What did the scentless solution remove?','a stain','the stage scenery','a red scarf','无气味清洁剂去掉了污渍。',1,'context'),q('What did it leave in the room?','no fragrance','a strong floral perfume','a faint orange-blossom scent','清洁剂没有留下任何香味。',1,'context'),q('What does scentless mean?','giving off no smell','having a strong pleasant smell','difficult to obtain','scentless 指无气味的。',1,'meaning'),q('Which product is scentless?','an unscented cleaner with no detectable odor','a lavender-scented paper','a perfume dabbed on a wrist','没有可察觉气味的清洁剂是 scentless。',1,'context')]);
P('sceptic','Sceptic comes from Greek skeptikos, “thoughtful or inquiring,” through Latin; it means someone who questions claims instead of accepting them easily.',C('sceptic.s1','怀疑论者','The sceptic asked for independent test results before believing the company’s claim about the new battery.','这位怀疑论者要求查看独立测试结果后，才相信公司关于新电池的说法。','The sceptic asked for test results / before believing / the company’s claim.','sceptic 指不轻信说法、会提出质疑的人。','他要求独立证据再相信宣传。'),M('The sceptic accepted the company’s claim immediately without asking for evidence or checking the test results.','The sceptic questioned the claim and requested independent test results.','不求证就立刻相信，不符合怀疑论者的态度。','meaning'),[q('What did the sceptic request?','independent test results','a scenic film','a schedule for the concert','怀疑论者要求查看独立测试结果。',1,'context'),q('What did the company claim about the battery?','that it was new and effective','that it had no scent','that it was a stage prop','怀疑论者先要求证据再相信公司的电池宣传。',1,'context'),q('What is a sceptic?','someone who questions whether claims are true','someone who accepts every claim immediately','a person who scatters seed','sceptic 指会质疑说法的人。',1,'meaning'),q('Which Greek word is linked to sceptic?','skeptikos, “inquiring”','skēnē, “stage”','scala, “ladder”','sceptic 源自希腊语 skeptikos，含有探究、质疑之意。',1,'word-formation')]);
P('sceptical','Sceptical is formed from sceptic and -al; it means not easily convinced and inclined to doubt.',C('sceptical.s1','怀疑的','The residents were sceptical of the quick repair promise because the contractor had missed three earlier deadlines.','居民对迅速修复的承诺持怀疑态度，因为承包商此前已错过三次期限。','The residents were sceptical of the promise / because earlier deadlines / had been missed.','sceptical 描写不容易被说服、倾向于怀疑的态度。','过去失约使居民不再轻信。'),M('The residents were sceptical of the promise because the contractor had met every deadline and provided proof.','The residents were sceptical because the contractor had missed earlier deadlines.','承包商按时完成并提供证据，不能解释居民的怀疑。','meaning'),[q('Why were residents sceptical of the repair promise?','the contractor had missed three deadlines','the contractor had already finished repairs','the scenic film was delayed','此前多次延误让居民怀疑迅速修复的承诺。',1,'context'),q('What does sceptical mean?','not easily convinced and inclined to doubt','certain that a claim is true','afraid of a loud sound','sceptical 指不轻信、持怀疑态度。',1,'meaning'),q('Which response is sceptical?','asking for evidence before accepting a surprising claim','believing a claim without checking it','repeating a promise as a fact','对令人惊讶的说法先要求证据体现 sceptical。',1,'context'),q('Which word is sceptical based on?','sceptic','scenario','scenery','sceptical 由 sceptic 加 -al 构成。',1,'word-formation')]);
P('scepticism','Scepticism is formed from sceptic and -ism, ultimately from Greek skeptikos; it means doubt about claims or the philosophical view that certain knowledge may be impossible.',C('scepticism.s1','怀疑态度；怀疑论','Her scepticism about the miracle cure led her to consult a doctor and read controlled-study results.','她对这种灵丹妙药持怀疑态度，因此咨询医生并阅读对照研究结果。','Her scepticism about the cure led her / to consult a doctor / and read study results.','scepticism 指对说法持怀疑态度，也可指一种哲学立场。','她以求证而非盲信来回应宣传。'),M('Her scepticism about the cure meant she trusted the advertisement immediately and refused to examine any evidence.','Her scepticism about the cure led her to seek medical advice and evidence.','立即轻信广告、拒绝查证与怀疑态度相反。','meaning'),[q('What did her scepticism lead her to do?','consult a doctor and read study results','buy the cure without checking it','write a film scenario','她对疗效持怀疑态度，因此咨询医生并查阅研究。',1,'context'),q('What is scepticism?','doubt about claims or a philosophical position','certainty that every claim is true','a written schedule','scepticism 指对说法的怀疑或相关哲学立场。',1,'meaning'),q('Which action shows scepticism?','checking independent trials before accepting a cure claim','sharing the advertisement as proven fact','ignoring all medical information','先查独立试验再接受疗效说法体现 scepticism。',1,'context'),q('What suffix appears in scepticism?','-ism','-less','-er','sceptic 加 -ism 构成名词 scepticism。',1,'word-formation')]);
P('schedule','Schedule comes from Latin schedula, “small sheet of paper,” through French; it can mean a list of planned times or arrange something for a particular time.',[C('schedule.s1','时间表；日程；进度表','The bus schedule shows the last departure from the hospital at 10:40 p.m.','公交时刻表显示，末班车晚上10点40分从医院发车。','The bus schedule shows / the last departure / from the hospital at 10:40.','schedule.s1 指列出活动或交通时间的计划表。','乘客据时刻表查看末班车时间。'),C('schedule.s2','安排；排定','The clinic scheduled the follow-up visit for Tuesday after the test results arrived.','检查结果出来后，诊所把复诊安排在星期二。','The clinic scheduled the follow-up / for Tuesday / after results arrived.','schedule.s2 作动词，指计划某事在特定时间发生。','复诊被排定在星期二。')],M('The bus schedule showed a 10:40 departure even though the buses never ran at that time and no timetable listed it.','The bus schedule listed the last departure at 10:40 p.m.','没有班次且时刻表未列出，不会显示10点40分发车。','meaning'),[q('When does the last bus leave the hospital?','10:40 p.m.','Tuesday morning','at the time of the scenic film','时刻表显示末班车晚上10点40分发车。',1,'context'),q('When did the clinic schedule the follow-up?','Tuesday','10:40 p.m.','before the test results arrived','诊所把复诊排定在星期二。',2,'context'),q('What is a schedule as a noun?','a list of planned times','a confirmed medical result','a written film outline','schedule 作名词指列出计划时间的表。',1,'meaning'),q('What does schedule mean as a verb?','arrange for something to happen at a particular time','look at every part quickly','question a claim','schedule 作动词指安排某事在特定时间发生。',2,'meaning')]);
P('scheduled','Scheduled is the past participle of schedule; it describes an event planned to happen at a particular time.',C('scheduled.s1','排定的；按时刻表的','The scheduled inspection will begin at 8 a.m., so the building manager unlocked the service entrance early.','排定的检查将于早上八点开始，因此楼宇经理提前打开了服务入口。','The scheduled inspection will begin / at 8 a.m. / so the entrance was opened early.','scheduled 描写已计划在某个特定时间发生的活动。','检查时间已排定。'),M('The inspection was scheduled for 8 a.m. even though nobody chose a time and the team had no plan to attend.','The inspection was scheduled for 8 a.m. and the building manager prepared for it.','无人选定时间、也无计划，不应称为 scheduled。','meaning'),[q('When will the inspection begin?','at 8 a.m.','after midnight without notice','when the concert ends','排定的检查将于早上八点开始。',1,'context'),q('Why did the manager unlock the entrance early?','the inspection was scheduled to begin at 8','the inspection had been cancelled','the building was a film set','经理因检查排定在八点开始而提前开门。',1,'context'),q('What does scheduled mean?','planned to happen at a particular time','happening unexpectedly','already completed long ago','scheduled 指计划在特定时间发生的。',1,'meaning'),q('Which event is scheduled?','a meeting set for 3 p.m. on Friday','a surprise visit with no chosen time','a rumor about a possible storm','已定在周五下午三点的会议是 scheduled event。',1,'context')]);
P('schematic','Schematic comes from Greek skhematikos, from schema (“form”); it can describe a simplified representation or name a drawing showing a system’s parts and connections.',[C('schematic.s1','示意的；概略的','The schematic map shows the subway lines clearly but leaves out realistic details such as buildings and trees.','这张示意地图清楚标出地铁线路，但省略了建筑和树木等写实细节。','The schematic map shows the subway lines / but leaves out / realistic details.','schematic.s1 作形容词，指用简化、约定方式呈现结构。','地图突出线路关系而非真实景观。'),C('schematic.s2','示意图','The electrician followed the schematic to connect the battery, switch, and lamp in the correct order.','电工按照示意图依次连接电池、开关和灯泡。','The electrician followed the schematic / to connect the battery, switch, / and lamp.','schematic.s2 作名词，指展示系统组成部分及连接关系的图。','图示电路元件的连接方式。')],M('The subway map was schematic because it included lifelike drawings of every building and tree in exact detail.','The subway map was schematic because it simplified the city to show only the train lines.','包含所有写实细节不符合简化示意图的特点。','meaning'),[q('What did the schematic map leave out?','realistic details such as buildings and trees','the subway lines themselves','the battery and switch','示意地图省略了写实细节，突出地铁线路。',1,'context'),q('What did the electrician connect by following the schematic?','a battery, switch, and lamp','subway stations and trees','the school’s open grounds','电工按照示意图连接电池、开关和灯泡。',2,'context'),q('What does schematic mean as an adjective?','simplified to show structure rather than realistic details','drawn with every detail accurately','secret and dishonest','schematic map 指简化展示结构的地图。',1,'meaning'),q('What is a schematic as a noun?','a drawing showing parts of a system and their connections','a realistic photograph of a city','a school plan that pays tuition','schematic 作名词指系统连接示意图。',2,'meaning')]);
P('scheme','Scheme comes from Greek skhema, “form or plan,” through Latin and French; it can be an organized plan, a dishonest secret plan, or make such a plan.',[C('scheme.s1','计划；方案；体制','The city introduced a recycling scheme that gives apartment buildings separate bins for paper, glass, and food waste.','市政府推出回收方案，为公寓楼分别设置纸张、玻璃和厨余垃圾桶。','The city introduced a recycling scheme / giving buildings separate bins / for different waste.','scheme.s1 指有组织地开展某事的计划或制度。','回收制度安排了分类垃圾桶。'),C('scheme.s2','阴谋；诡计','The two brokers devised a scheme to hide the fees from customers and keep the extra money.','两名经纪人设计阴谋，向客户隐瞒费用并私吞额外款项。','The brokers devised a scheme / to hide fees / and keep the money.','scheme.s2 指秘密且不诚实的计划。','经纪人密谋隐瞒收费。'),C('scheme.s3','密谋；图谋','The fraudsters schemed to steal the museum’s donation fund by creating a fake account.','诈骗者密谋开设假账户，盗取博物馆捐款。','The fraudsters schemed / to steal the donation fund / with a fake account.','scheme.s3 作动词，指策划秘密、常常不诚实的计划。','诈骗者策划偷取捐款。')],M('The brokers’ scheme was an honest public plan that showed every fee clearly to customers.','The brokers’ scheme secretly hid fees from customers so they could keep extra money.','公开透明且诚实的计划不是此处所说的阴谋。','meaning'),[q('What did the city’s recycling scheme provide?','separate bins for different waste','a fake account for donations','a schematic diagram of a circuit','回收方案为不同废物安排了分类垃圾桶。',1,'context'),q('What was dishonest about the brokers’ scheme?','they hid fees and kept the extra money','they showed every fee publicly','they funded a scholarship','经纪人密谋隐瞒费用并私吞款项。',2,'context'),q('What did the fraudsters scheme to do?','steal the museum’s donation fund','connect a battery to a lamp','teach pupils in a schoolroom','诈骗者密谋盗取博物馆捐款。',3,'context'),q('Which use of scheme means an organized public plan?','the city introduced a recycling scheme','the brokers devised a scheme to hide fees','the fraudsters schemed to steal funds','第一句中的 scheme 指有组织的回收计划。',1,'meaning')]);
P('scheming','Scheming is formed from scheme and -ing; it describes someone given to making sly, selfish plans.',C('scheming.s1','搞阴谋的；诡计多端的','The scheming treasurer secretly altered the donation records to make it appear that the missing money had been spent legally.','这个诡计多端的财务主管偷偷篡改捐款记录，假装失踪的钱已合法支出。','The scheming treasurer altered the records / to disguise / the missing money.','scheming 指惯于暗中策划自私或不诚实计划的。','财务主管隐瞒资金去向。'),M('The scheming treasurer openly reported every transaction and invited auditors to inspect all records.','The scheming treasurer secretly changed the records to conceal missing money.','公开报告账目且邀请审计，与暗中策划欺诈相反。','meaning'),[q('What did the scheming treasurer alter?','the donation records','the subway map','the scholarship application','财务主管偷偷篡改了捐款记录。',1,'context'),q('Why did the treasurer change the records?','to disguise missing money','to explain a schematic circuit','to award a scholarship','篡改记录是为了掩盖失踪资金。',1,'context'),q('What does scheming describe?','making sly, selfish plans','studying a subject deeply','teaching a class','scheming 指暗中策划自私的计划。',1,'meaning'),q('Which person is scheming?','an officer secretly falsifying records for personal gain','a student applying for a scholarship openly','an electrician following a circuit diagram','为个人利益暗中伪造记录的人是 scheming。',1,'context')]);
P('schism','Schism comes from Greek skhisma, “cleft or split,” from skhizein (“split”); it means a separation into opposing groups over beliefs.',C('schism.s1','分裂','A schism divided the organization after members disagreed about whether to accept the new charter.','成员因是否接受新章程意见不合，组织因此分裂。','A schism divided the organization / after members disagreed / about the new charter.','schism 指因信念或意见分歧而形成对立派别。','不同意见导致组织分裂。'),M('The organization avoided a schism because every member agreed on the charter and remained united.','The organization suffered a schism when members split into opposing groups over the charter.','意见一致且保持团结，不构成分裂。','meaning'),[q('What disagreement caused the organization’s schism?','whether to accept the new charter','how to connect the lamp and battery','which student should receive a scholarship','成员对新章程意见不合，导致组织分裂。',1,'context'),q('What is a schism?','a separation into opposing groups','an organized recycling plan','a realistic drawing','schism 指意见不合造成的分裂。',1,'meaning'),q('Which group experienced a schism?','members divided over a shared belief','a class agreed unanimously on a plan','a school opened a new classroom','成员因共同信念分歧而分裂的组织经历了 schism。',1,'context'),q('Which Greek verb is related to schism?','skhizein, “split”','skhema, “form”','skēnē, “tent”','schism 源自表示“分裂”的希腊词根。',1,'word-formation')]);
P('schist','Schist comes from Greek skhistos, “split,” from skhizein; it is a metamorphic rock with aligned minerals that allow it to cleave into sheets.',C('schist.s1','片岩','The geologist identified schist by its visible mineral layers and the thin sheets that broke along them.','地质学家根据可见的矿物层和沿层裂开的薄片辨认出片岩。','The geologist identified schist / by its aligned mineral layers / and sheet-like breaks.','schist 指矿物排列成层、容易沿层片状裂开的变质岩。','岩石沿矿物层裂开。'),M('The geologist identified the rock as schist even though it had no aligned minerals and could not split into sheets.','The geologist identified the rock as schist because its aligned minerals formed layers that split into sheets.','没有矿物层且无法片状裂开的岩石不符合片岩特征。','meaning'),[q('What feature helped identify the schist?','aligned mineral layers','a pleasant scent','a film scenario','片岩可见矿物层，并能沿层裂成薄片。',1,'context'),q('How did pieces of the schist break?','along layers into thin sheets','into round beads','only into liquid','片岩沿矿物层裂成薄片。',1,'context'),q('What is schist?','a metamorphic rock with aligned minerals','a type of scholarship','a painted stage background','schist 是矿物排列成层的变质岩。',1,'meaning'),q('Which Greek idea is reflected in the name schist?','split into layers','pleasant smell','public scene','schist 的希腊词源含有“可裂开”的意思。',1,'word-formation')]);
P('scholar','Scholar comes from Latin scholaris, from schola (“school”); it can mean a person with deep academic knowledge or a student receiving a scholarship.',[C('scholar.s1','学者','The scholar spent decades comparing medieval letters to understand how trade laws changed.','这位学者花了数十年比较中世纪书信，以了解贸易法律的变化。','The scholar spent decades comparing letters / to understand / changing trade laws.','scholar.s1 指在某学术领域具有丰富知识的人。','学者长期研究历史文献。'),C('scholar.s2','奖学金生','As a scholarship scholar, Lina attends the university without paying tuition for her engineering degree.','作为一名获奖学金的学生，莉娜无需支付工程学学位的学费。','Lina attends the university as a scholar / without paying tuition / for engineering.','scholar.s2 指获得奖学金资助的学生。','奖学金资助莉娜的大学学习。')],M('The scholar had no academic knowledge or research experience and never studied any subject.','The scholar had extensive knowledge of trade law and researched historical letters.','没有学术知识或研究经历的人不能称为此处的学者。','meaning'),[q('What did the scholar compare?','medieval letters','a stage background','school playgrounds','学者比较中世纪书信来研究贸易法律变化。',1,'context'),q('How does Lina attend university?','with tuition covered by a scholarship','by paying double tuition','as a schoolroom teacher','奖学金资助莉娜学习工程学。',2,'context'),q('What does scholar mean in the research example?','a person with deep academic knowledge','a student receiving tuition support','a plan to divide an organization','研究例句中的 scholar 指学者。',1,'meaning'),q('What does scholar mean in Lina’s example?','a student who has received a scholarship','a historian comparing old letters','a person who draws a schematic','Lina 是获得奖学金的学生。',2,'meaning')]);
P('scholarly','Scholarly is formed from scholar and -ly; it describes serious, deep study or work showing extensive knowledge.',C('scholarly.s1','学者的；学术的','The article offered a scholarly analysis of the letters, citing archival records and comparing several translations.','这篇文章对书信作了学术分析，引用档案记录并比较多个译本。','The article offered a scholarly analysis / citing records / and comparing translations.','scholarly 指涉及严肃深入研究或体现丰富学识的。','文章基于档案和译本进行研究。'),M('The article was scholarly even though it gave no evidence, cited no sources, and relied only on guesses.','The article was scholarly because it cited archival records and compared translations.','没有证据和来源的猜测不符合严谨学术研究。','meaning'),[q('What sources supported the scholarly analysis?','archival records and several translations','a rumor about a miracle cure','a costume schedule','学术分析引用档案记录并比较多个译本。',1,'context'),q('What does scholarly mean?','involving serious study or showing knowledge','based on unsupported guesses','planned for a fixed time','scholarly 指严肃深入研究或体现学识的。',1,'meaning'),q('Which project is scholarly?','a documented study comparing multiple historical sources','a rumor repeated without evidence','a quick guess about a film ending','基于多个历史来源的有据研究属于 scholarly work。',1,'context'),q('Which noun is scholarly based on?','scholar','schoolroom','scheme','scholarly 由 scholar 加 -ly 构成。',1,'word-formation')]);
P('scholarship','Scholarship is formed from scholar and -ship; it can mean money supporting a student’s education or serious academic study and knowledge.',[C('scholarship.s1','奖学金','A scholarship covered Noor’s tuition and books after she earned the highest score in the science competition.','诺尔在科学竞赛中取得最高分后，获得奖学金支付学费和书本费。','A scholarship covered Noor’s tuition and books / after her high score / in science.','scholarship.s1 指用于支付学生教育费用的钱。','奖学金支付学费和书费。'),C('scholarship.s2','学问；学术成就','The book’s careful scholarship is clear in its detailed notes and accurate use of primary sources.','这本书严谨的学术功底体现在详尽注释和对一手资料的准确运用上。','The book’s scholarship is clear / in detailed notes / and accurate primary sources.','scholarship.s2 指严肃的研究和学术知识。','注释与一手资料体现学术功底。')],M('Noor’s scholarship paid nothing toward her education and required her family to cover every tuition bill.','Noor’s scholarship paid her tuition and book costs.','奖学金用于支付教育费用，不是完全不提供资助。','meaning'),[q('What did Noor’s scholarship cover?','tuition and books','a stage scenery change','the cost of a scenic film','奖学金支付了诺尔的学费和书本费。',1,'context'),q('What showed the book’s scholarship?','detailed notes and accurate primary sources','unsupported rumors and missing references','a school’s new schedule','注释详尽并准确引用一手资料体现书中的学术功底。',2,'context'),q('What does scholarship mean in Noor’s example?','money given to pay for education','a student’s serious academic research','a group divided over beliefs','这里 scholarship 指用于教育的资助金。',1,'meaning'),q('What does scholarship mean in the book example?','serious study and academic knowledge','tuition assistance only','a written scenario','这里 scholarship 指学术研究水平。',2,'meaning')]);
P('scholastic','Scholastic comes from Latin scholasticus, from Greek scholastikos (“of study”); it can describe school or academic work, or a medieval follower of scholasticism.',[C('scholastic.s1','学业的；学校的','The scholastic award recognized students who improved their grades while completing community service.','这项学业奖表彰了在完成社区服务的同时提高成绩的学生。','The scholastic award recognized students / who improved grades / while serving the community.','scholastic.s1 指与学校教学或学生学业有关的。','奖项表彰学生学业进步。','该词形容与学习或学业有关。'),C('scholastic.s2','经院哲学家','The medieval scholastic debated how reason and religious authority could be reconciled.','这位中世纪经院哲学家探讨理性与宗教权威如何协调。','The medieval scholastic debated / how reason and authority / could be reconciled.','scholastic.s2 作名词，指中世纪经院哲学传统的追随者。','哲学家讨论理性和权威的关系。','名词用法特指经院哲学家。')],M('The scholastic award was unrelated to school or academic work and recognized only the fastest scenic driver.','The scholastic award recognized students for academic improvement and community service.','与学业无关的驾驶奖不符合 scholastic 的学校义。','meaning'),[q('Who received the scholastic award?','students who improved their grades','the fastest scenic driver','a medieval philosopher only','奖项表彰了学业进步并参与社区服务的学生。',1,'context'),q('What did the medieval scholastic debate?','the relationship between reason and religious authority','how to schedule a school bus','whether a scenic road is beautiful','经院哲学家讨论理性与宗教权威能否协调。',2,'context'),q('What does scholastic mean in “scholastic award”?','connected with school or academic work','a medieval follower of scholasticism','related to stage scenery','scholastic award 指学业相关奖项。',1,'meaning'),q('Who is a scholastic in the medieval example?','a follower of medieval scholasticism','a student receiving tuition funding','a scholar comparing letters','此处 scholastic 是经院哲学传统的追随者。',2,'meaning')]);
P('school','School comes from Greek skholē, originally “leisure for study,” through Latin schola; it can mean an educational place, a shared artistic/intellectual group, a group of fish, or train someone.',[C('school.s1','学校','The school opened its doors early so students could eat breakfast before the first lesson.','学校提早开门，让学生在第一节课前吃早餐。','The school opened early / so students could eat breakfast / before class.','school.s1 指教授学生的机构或场所。','学生到学校上课。'),C('school.s2','学派；流派','The painter belongs to a school of artists who use bold colors and simplified shapes.','这位画家属于一个使用鲜明色彩和简化形状的艺术流派。','The painter belongs to a school / whose artists use bold colors / and simple shapes.','school.s2 指共享风格或观念的艺术家、思想家群体。','画家与同风格艺术家属于一个流派。'),C('school.s3','（鱼等的）群','A school of sardines flashed silver beneath the boat and turned together toward deeper water.','一群沙丁鱼在船下闪着银光，一起转向更深的水域。','A school of sardines flashed beneath the boat / and turned / toward deeper water.','school.s3 指成群一起游动的鱼或海洋动物。','沙丁鱼群一起游动。'),C('school.s4','训练；使学会','The veteran guide schooled the new recruits in reading trail markers before they entered the forest.','老向导在新队员进森林前训练他们辨认步道标记。','The veteran guide schooled the recruits / in reading trail markers / before entering the forest.','school.s4 作动词，指训练某人掌握技能或行为方式。','新队员接受辨认路标训练。')],M('The school opened its doors as a grocery store where no students received lessons.','The school opened its doors early so students could attend their lessons.','没有教学活动的杂货店不是学校。','meaning'),[q('Why did the school open early?','students could eat breakfast before class','artists could paint a scene','sardines could swim beneath a boat','学校提早开门让学生先吃早餐再上课。',1,'context'),q('What did the painter’s school of artists share?','bold colors and simplified shapes','a schoolroom and a lunch rota','a common salary scholarship','艺术流派中的画家使用鲜明色彩和简化形状。',2,'context'),q('What moved beneath the boat?','a school of sardines','a school of children','a school bus','一群沙丁鱼在船下游动。',3,'context'),q('What did the veteran guide school the recruits to do?','read trail markers','write a film scenario','collect wildflowers','老向导训练新队员辨认步道标记。',4,'context')]);
P('school grounds','School grounds combines school and grounds; it means the open area and land belonging to a school.',C('school grounds.s1','校园；校内场地','Students planted native flowers along the school grounds after the science club removed invasive weeds.','科学社团清除入侵杂草后，学生在校园场地边种植本地花卉。','Students planted flowers on the school grounds / after the club / removed weeds.','school grounds 指属于学校的户外场地和土地。','学生在校内土地种花。'),M('The school grounds were the indoor classroom where students sat at desks and never went outside.','The school grounds were the outdoor land around the school where students planted flowers.','室内教室不是学校的户外场地。','meaning'),[q('Where did students plant native flowers?','along the school grounds','inside the schoolroom','beneath the theater stage','学生在校园场地边种植本地花卉。',1,'context'),q('What did the science club remove first?','invasive weeds','school desks','scenic backgrounds','科学社团先清除了入侵杂草。',1,'context'),q('What are school grounds?','the open land belonging to a school','the interior of one classroom','a group of artists','school grounds 指学校所属的户外场地。',1,'meaning'),q('Which is on the school grounds?','a school’s playing field and garden','a scholarship student’s private bedroom','a film’s final scene','学校的操场和花园属于 school grounds。',1,'context')]);
P('schoolchild','Schoolchild combines school and child; it means a child who attends school.',C('schoolchild.s1','学童；小学生','The schoolchild carried a lunch box and a library book on the walk to class.','这名学童步行上课时带着午餐盒和一本图书馆借书。','The schoolchild carried a lunch box / and a library book / to class.','schoolchild 指正在上学的儿童。','孩子带着上课用品去学校。'),M('The schoolchild was an adult university professor who had never attended primary or secondary school.','The schoolchild was a young student carrying books to class.','成年教授不是此处的学童。','meaning'),[q('What did the schoolchild carry?','a lunch box and a library book','a film scenery panel','a scenic camera','学童带着午餐盒和图书馆借书去上课。',1,'context'),q('Where was the child going?','to class','to a theater stage','to a fish school','学童正步行去上课。',1,'context'),q('What is a schoolchild?','a child who attends school','a teacher who writes a schedule','a person who receives film royalties','schoolchild 指正在上学的孩子。',1,'meaning'),q('Which person is a schoolchild?','an eight-year-old carrying books to lessons','a professor teaching graduate students','a fish swimming with a school','八岁并带书去上课的孩子是 schoolchild。',1,'context')]);
P('schoolmate','Schoolmate combines school and mate; it means someone who attends the same school as another person.',C('schoolmate.s1','同学；同窗','Jamal met a former schoolmate at the reunion and remembered their shared science project.','贾马尔在同学会上遇到以前的同学，想起他们一起做过的科学项目。','Jamal met a former schoolmate / and remembered / their science project.','schoolmate 指与自己上同一所学校的人。','两人曾在同一所学校读书。'),M('Jamal called the stranger his schoolmate even though they had attended different schools and never met before.','Jamal called him a schoolmate because they had attended the same school.','从未同校也从未见过的人不是同学。','meaning'),[q('Where did Jamal meet his schoolmate?','at a reunion','in a medical scanner','on the coastal road','贾马尔在同学会上遇到以前的同学。',1,'context'),q('What did they remember doing together?','a science project','writing a theater scenario','scanning the school grounds','他们想起了曾一起做的科学项目。',1,'context'),q('What is a schoolmate?','someone who attends the same school','a child who owns a school','a student who receives tuition funding','schoolmate 指同校同学。',1,'meaning'),q('Which pair are schoolmates?','two people who attended the same school','a teacher and a student at different schools','two fish in a school','曾就读同一所学校的两个人是 schoolmates。',1,'context')]);
P('schoolroom','Schoolroom combines school and room; it means a room used for teaching a class, especially in a school.',C('schoolroom.s1','教室','The old schoolroom still has wooden desks arranged in rows and a large chalkboard at the front.','这间旧教室仍摆着成排木桌，前面有一块大黑板。','The old schoolroom has wooden desks / in rows / and a chalkboard.','schoolroom 指学校中用于课堂教学的房间。','教室里有课桌和黑板。'),M('The schoolroom was the outdoor field behind the building where no lessons could be taught.','The schoolroom was the indoor room with desks and a board for lessons.','室外操场不是用于课堂教学的房间。','meaning'),[q('What furniture remained in the old schoolroom?','wooden desks and a chalkboard','a painted forest backdrop','a medical scan machine','旧教室里有成排木桌和黑板。',1,'context'),q('Where was the chalkboard?','at the front of the room','on the school grounds','inside the river scenery','黑板位于教室前方。',1,'context'),q('What is a schoolroom?','a room used to teach a class','the open land around a school','a group of students sharing a school','schoolroom 指用来上课的教室。',1,'meaning'),q('Which space is a schoolroom?','an indoor room with desks where a teacher gives lessons','an outdoor playground with no classroom','a stage showing a scenic film','有课桌并用于教学的室内空间是 schoolroom。',1,'context')]);
P('schoolwork','Schoolwork combines school and work; it means lessons and tasks pupils must complete for their classes.',C('schoolwork.s1','学校作业','Priya finished her schoolwork before dinner so she could join the family walk afterward.','普丽娅在晚饭前完成学校作业，之后便能和家人一起散步。','Priya finished her schoolwork / before dinner / to join the family walk.','schoolwork 指学生为课程完成的学习任务。','她先完成作业再与家人散步。'),M('Priya finished her schoolwork by leaving every assignment blank and submitting no class tasks.','Priya finished her schoolwork by completing the assignments due that day.','不完成作业却交白卷，不算完成 schoolwork。','meaning'),[q('When did Priya finish her schoolwork?','before dinner','after the family walk ended','during the school reunion','普丽娅在晚饭前完成学校作业。',1,'context'),q('What could she do after finishing?','join the family walk','skip school permanently','scavenge in a shed','完成作业后她可以和家人散步。',1,'context'),q('What does schoolwork mean?','lessons and tasks pupils do for class','the land surrounding a school','a child attending school','schoolwork 指学生为课程完成的学习任务。',1,'meaning'),q('Which is schoolwork?','a worksheet due for tomorrow’s class','a teacher’s salary receipt','a film’s scenic background','明天上课要交的练习题属于 schoolwork。',1,'context')]);
P('science','Science comes from Latin scientia, “knowledge,” from scire (“know”); it can mean systematic knowledge of the natural world or a particular field of that study.',[C('science.s1','科学；理科','Science explains the water cycle through observation, measurements, and experiments that can be repeated.','科学通过观察、测量和可重复的实验来解释水循环。','Science explains the water cycle / through observation / and repeatable experiments.','science.s1 指通过观察与检验获得的自然世界知识。','科学用可重复实验检验解释。'),C('science.s2','一门科学；学科体系','Ecology is a science that studies how organisms interact with one another and their environments.','生态学是一门研究生物彼此及其与环境相互作用的科学。','Ecology is a science / that studies organism interactions / with each other and environments.','science.s2 指自然科学中的某个具体学科。','生态学研究生物与环境。')],M('Science explained the water cycle through guesses that could never be observed, measured, or tested again.','Science explained the water cycle using observations and repeatable tests.','不可观察、测量或复验的猜测不符合科学方法。','meaning'),[q('How does science explain the water cycle?','with observation, measurements, and repeatable experiments','with unsupported rumors','with a stage scenery change','科学使用观察、测量和可重复实验解释水循环。',1,'context'),q('What does ecology study?','interactions among organisms and their environments','the structure of film scripts','how to award scholarships','生态学研究生物之间及其与环境的相互作用。',2,'context'),q('What does science mean in the first example?','systematic knowledge gained through observation and testing','a single academic subject only','a rumor about a cure','第一句 science 指通过观察和检验获得的知识体系。',1,'meaning'),q('What does science mean in “ecology is a science”?','a particular field of systematic study','knowledge gained only by guessing','a school’s teaching room','这里 science 指一门具体学科。',2,'meaning')]);
P('scientific','Scientific is formed from science and -ific; it means concerning science or using methods that follow fixed, testable rules.',[C('scientific.s1','科学的；科学上的','The team used a scientific method, repeating the trial and recording every measurement before drawing a conclusion.','团队采用科学方法，重复试验并记录每项测量后才得出结论。','The team used a scientific method / repeating the trial / and recording measurements.','scientific 指与科学有关，或遵循系统、可检验的方法。','重复试验并记录数据体现科学方法。','-ific 构成形容词，表示“具有……性质的”。')],M('The team called its conclusion scientific even though it ran no tests and ignored every measurement.','The team called its conclusion scientific because it repeated the trial and recorded measurements.','不做测试也不记录数据，不能称为科学方法。','meaning'),[q('What did the team repeat?','the trial','the school schedule','the film’s final scene','团队重复了试验并记录数据。',1,'context'),q('What did they record before drawing a conclusion?','every measurement','only a rumor','the schoolroom scenery','团队在结论前记录了每项测量。',1,'context'),q('What does scientific mean?','concerning science or using testable methods','based only on personal belief','a loud public argument','scientific 指科学相关或遵循可检验方法的。',1,'meaning'),q('Which study is scientific?','one that repeats tests and reports measurements','one that ignores data and relies on guesses','one that changes the scenery','重复测试并报告数据的研究是 scientific。',1,'context')]);
P('scientifically','Scientifically is formed from scientific and -ally; it means using experiments and evidence, or in an orderly and methodical way.',[C('scientifically.s1','按科学方法地','The vaccine was scientifically tested in controlled trials before regulators reviewed the results.','疫苗在监管机构审查结果前，经过了对照试验的科学测试。','The vaccine was scientifically tested / in controlled trials / before review.','scientifically.s1 指用实验、证据和检验方法开展。','疫苗接受了对照试验。'),C('scientifically.s2','系统地；有条理地','The historian organized the archive scientifically, cataloging each letter by date, author, and subject.','历史学家有条理地整理档案，按日期、作者和主题编目每封信。','The historian organized the archive scientifically / cataloging letters / by date and subject.','scientifically.s2 可指系统、方法性地整理或进行工作。','档案按统一字段整理。')],M('The vaccine was scientifically tested even though no trial was conducted and no evidence was collected.','The vaccine was scientifically tested in controlled trials with recorded evidence.','没有试验或证据不符合科学测试。','meaning'),[q('How was the vaccine tested?','in controlled trials','by rumor alone','through a stage performance','疫苗经过了对照试验测试。',1,'context'),q('How did the historian organize the archive?','by cataloging letters by date, author, and subject','by scattering papers randomly','by writing a scenic script','历史学家按日期、作者和主题系统整理档案。',2,'context'),q('What does scientifically mean in the vaccine example?','using experiments and evidence','in a random untested way','with a pleasant scent','疫苗句中的 scientifically 指采用实验和证据。',1,'meaning'),q('What does scientifically mean in the archive example?','in an orderly, methodical way','only with laboratory equipment','in a loud public scene','档案句中的 scientifically 指有条理地整理。',2,'meaning')]);
P('scientist','Scientist is formed from science and -ist; it means someone who systematically investigates the natural or social world in a scientific field.',C('scientist.s1','科学家','The scientist measured air samples from the valley to find out why pollution levels rose overnight.','科学家测量了山谷中的空气样本，以查明污染水平为何在一夜之间升高。','The scientist measured air samples / to find out / why pollution rose.','scientist 指在某个科学领域系统研究自然或社会世界的人。','研究者通过测量空气样本寻找原因。'),M('The scientist determined the pollution level by guessing without collecting any air samples or measurements.','The scientist measured air samples to investigate the pollution increase.','不采集样本或测量数据只靠猜测，不是科学研究。','meaning'),[q('What did the scientist measure?','air samples from the valley','schoolwork from the classroom','the width of a scenic road','科学家测量山谷空气样本。',1,'context'),q('What question was the scientist investigating?','why pollution rose overnight','why the school had a schism','how to write a scenery outline','科学家研究污染水平为何一夜之间升高。',1,'context'),q('What is a scientist?','someone who systematically investigates a field','someone who accepts rumors without evidence','someone who awards a scholarship','scientist 指系统研究某个领域的人。',1,'meaning'),q('Which worker is a scientist?','a researcher testing how plants respond to different light levels','a cashier scheduling a shop rota','a critic making a scene','研究植物对光照反应的人是 scientist。',1,'context')]);
P('scissors','Scissors comes through Old French cisoires from Latin caedere (“cut”); it names a two-bladed cutting tool or, in a less common count use, one act of cutting.',[C('scissors.s1','剪刀','Use scissors to trim the paper around the photograph without cutting through the printed border.','用剪刀修剪照片周围的纸张，不要剪到印刷边框。','Use scissors to trim the paper / around the photograph / without cutting its border.','scissors.s1 指两片刀刃相互运动的切割工具。','剪刀修剪照片周围纸张。'),C('scissors.s2','一次剪裁','One careful scissors was enough to remove the loose thread from the costume.','仔细剪一刀，就足以剪掉服装上的松线。','One careful scissors removed / the loose thread / from the costume.','scissors.s2 指用剪刀进行的一次剪裁动作。','剪刀的一次剪裁去掉了松线。')],M('She cut the paper with scissors by rubbing it between her fingers without using any blades.','She cut the paper with scissors by closing the two blades around it.','不用刀刃而用手指摩擦不是用剪刀剪。','meaning'),[q('What did the scissors trim?','paper around a photograph','a science experiment','the scenery behind the stage','剪刀用来修剪照片周围的纸张。',1,'context'),q('What did one careful scissors remove?','a loose thread from the costume','the entire costume','a medical scan','仔细剪一刀剪掉了服装上的松线。',2,'context'),q('What are scissors?','a tool with two blades that cut against each other','a tool for weighing parcels','a written school schedule','scissors 是两片刀刃相互运动的切割工具。',1,'meaning'),q('What does scissors mean in “one careful scissors”?','one act of cutting with the tool','a pair of stage scissors only','a scene in a play','此处 scissors 指用剪刀进行的一次剪裁。',2,'meaning')]);
P('scoff','Scoff comes from Middle English scoff, probably from a Scandinavian source; it means to mock or, informally, to eat quickly and greedily.',[C('scoff.s1','嘲笑；嘲弄','The coach did not scoff at the beginner’s first attempt; she offered one useful correction instead.','教练没有嘲笑初学者的第一次尝试，而是给出了一条有用的改进建议。','The coach did not scoff / at the beginner’s first attempt / but offered advice.','scoff.s1 指以嘲弄的方式谈论或对待某人某事。','教练没有嘲笑初学者。'),C('scoff.s2','狼吞虎咽地吃','After the long hike, the children scoffed their sandwiches before the bus arrived.','长途徒步后，孩子们在公交车到来前狼吞虎咽地吃掉了三明治。','The children scoffed their sandwiches / after the long hike / before the bus arrived.','scoff.s2 是非正式用法，指快速而贪婪地吃东西。','孩子们很快吃完三明治。')],M('The coach scoffed at the beginner by patiently praising the effort and giving kind advice.','The coach scoffed at the beginner by mocking the attempt.','耐心称赞并友善建议不是嘲笑。','meaning'),[q('How did the coach respond to the attempt?','she avoided mocking it and gave useful advice','she laughed at the beginner','she canceled the bus','教练没有嘲笑尝试，而是给了建议。',1,'context'),q('What did the children do after hiking?','they ate their sandwiches quickly','they mocked the driver','they left the food untouched','孩子们徒步后很快吃掉三明治。',2,'context'),q('What does scoff mean in the coach example?','to mock or speak about something contemptuously','to praise someone sincerely','to measure a trail','此处 scoff 指嘲笑或嘲弄。',1,'meaning'),q('What does scoff mean in the sandwich example?','to eat quickly and greedily','to refuse food proudly','to pack a meal for later','此处 scoff 是非正式的“狼吞虎咽地吃”。',2,'meaning')]);
P('scold','Scold is recorded in Middle English and is related to an older word for a harsh or abusive person; it means to angrily criticize someone for wrongdoing.',[C('scold.s1','责骂；斥责','The librarian scolded Ben for shouting in the reading room, then reminded him to speak quietly.','本在阅览室大声喊叫，图书管理员斥责了他，并提醒他轻声说话。','The librarian scolded Ben / for shouting / in the reading room.','scold.s1 指因某人做错事而生气地责备。','本因在阅览室喊叫受斥责。'),C('scold.s2','唠叨地责备','Rather than scold about every small delay, Mara kept criticizing the team in a complaining voice all morning.','玛拉没有只针对一次小延误，而是一上午都用抱怨的口吻不停责备团队。','Mara kept scolding the team / in a complaining voice / all morning.','scold.s2 指以抱怨口吻持续批评、唠叨责备。','她持续抱怨并批评团队。')],M('The librarian scolded Ben by telling him calmly that the loud shouting was perfectly acceptable.','The librarian scolded Ben for shouting and told him to be quiet.','认可喊叫不构成责备；斥责是因不当行为而生气批评。','meaning'),[q('Why did the librarian scold Ben?','he shouted in the reading room','he returned a book early','he spoke quietly','本因在阅览室喊叫而受斥责。',1,'context'),q('How did Mara criticize the team?','in a complaining voice throughout the morning','with one brief compliment','by silently leaving the room','玛拉一上午都用抱怨口吻批评团队。',2,'context'),q('What does scold mean in the librarian example?','to angrily tell someone they have done wrong','to congratulate someone for a success','to ask someone for directions','此处 scold 指因错误行为而责备。',1,'meaning'),q('Which action is scolding in the second example?','repeatedly criticizing the team in a complaining tone','praising every small improvement','giving the team a map','持续用抱怨口吻批评是唠叨地责备。',2,'meaning')]);
P('scolding','Scolding is the -ing form of scold and is also a noun for an angry reprimand.',C('scolding.s1','训斥；责骂','After the spilled paint, Luis received a scolding for leaving the studio floor uncovered.','颜料洒出后，路易斯因没有遮好画室地面而挨了训斥。','Luis received a scolding / for leaving the floor uncovered / after paint spilled.','scolding.s1 是因某人做错事而进行的生气训斥。','路易斯因未保护地面而挨批评。'),M('Luis received a scolding when the teacher quietly praised his careful cleanup and said he had done nothing wrong.','Luis received a scolding for failing to cover the floor before painting.','安静称赞且认定他没做错不是训斥。','meaning'),[q('Why was Luis given a scolding?','he left the floor uncovered before paint spilled','he cleaned every brush','he arrived before the studio opened','路易斯因没有遮好地面而挨训。',1,'context'),q('What happened after the paint spilled?','Luis was reprimanded','the floor was already protected','the teacher praised an unrelated sculpture','颜料洒出后，路易斯受到了训斥。',1,'context'),q('What is a scolding?','an angry reprimand for something done wrong','a quiet invitation to a meal','a tool for lifting paint cans','scolding 指因做错事而受到的生气训斥。',1,'meaning'),q('Which event is a scolding?','a teacher angrily reprimands a pupil for breaking a rule','a teacher thanks a pupil for following instructions','a pupil paints a wall carefully','老师因学生违规而生气责备，属于 scolding。',1,'context')]);
P('scoop','Scoop is probably related to Dutch schope (“shovel”); it is a rounded lifting tool and the act of lifting something with it.',[C('scoop.s1','勺；舀子','A metal scoop measured one cup of grain before the miller poured it into the sack.','磨坊工把谷物倒进袋子前，用金属舀子量了一杯。','A metal scoop measured one cup / of grain / before it went into the sack.','scoop.s1 指像小铲子的舀取工具。','金属舀子量谷物。'),C('scoop.s2','舀取；端起','She scooped the sleeping kitten gently into both hands and carried it away from the road.','她轻轻把熟睡的小猫捧到双手中，从路边抱走。','She scooped the kitten / gently into both hands / away from the road.','scoop.s2 指用舀子或合拢的手掌把东西托起或移走。','她用双手捧起小猫。')],M('She scooped the kitten by pushing it away with a broom and never lifting it.','She scooped the kitten into her cupped hands and lifted it from the road.','scoop 表示托起或舀起，不是把东西推开。','meaning'),[q('What did the metal scoop measure?','one cup of grain','a cup of paint','a kitten’s weight','金属舀子量了一杯谷物。',1,'context'),q('How did she move the kitten?','she lifted it gently into both hands','she chased it into the road','she measured it with a ruler','她轻轻把小猫捧到双手中抱走。',2,'context'),q('What is a scoop in the first example?','a rounded tool used for lifting or measuring material','a flat ruler for drawing lines','a sack for storing grain','此处 scoop 是舀取工具。',1,'meaning'),q('What does scoop mean in the kitten example?','to lift or move something with cupped hands','to frighten an animal away','to measure a road','此处 scoop 指用合拢的手掌托起。',2,'meaning')]);
P('scope','Scope comes from Greek skopos (“target, aim”) through Latin and French; it means the range covered by a subject or the freedom to act.',[C('scope.s1','范围；范畴','The report’s scope covers traffic, housing, and public health, but excludes school funding.','报告的范围涵盖交通、住房和公共卫生，但不包括学校经费。','The report’s scope covers three subjects / but excludes / school funding.','scope.s1 指主题、计划或法律所涵盖的范围。','报告列出涵盖与排除的领域。'),C('scope.s2','机会；余地','The revised schedule gives the engineers more scope to test two designs before choosing one.','修订后的日程让工程师有更多余地在选定方案前测试两种设计。','The revised schedule gives engineers more scope / to test two designs / before choosing.','scope.s2 指采取行动或发展的机会、自由或余地。','工程师获得更多测试余地。')],M('The scope of the report included every possible topic, even though it explicitly excluded school funding.','The report’s scope covered traffic, housing, and public health, while excluding school funding.','scope 是实际涵盖的领域；明示排除的内容不在范围内。','meaning'),[q('Which subjects are within the report’s scope?','traffic, housing, and public health','school funding only','sports and astronomy','报告范围包括交通、住房和公共卫生。',1,'context'),q('What opportunity does the revised schedule provide?','time to test two designs','permission to ignore both designs','a rule banning all testing','修订日程让工程师有机会测试两种设计。',2,'context'),q('What does scope mean in the report example?','the area a subject or plan covers','a person who records scores','the act of lifting with a shovel','报告句中的 scope 指涵盖领域。',1,'meaning'),q('What does scope mean in the schedule example?','freedom or opportunity to act','a fixed list of excluded topics','a measurement of temperature','日程句中的 scope 指行动余地。',2,'meaning')]);
P('scorch','Scorch is from Middle English scorchen, probably of Scandinavian origin; it means to burn a surface with dry heat or to damage plants by heat or wind.',[C('scorch.s1','烧焦；烫糊','The iron scorched the collar when Nia left it face down on the shirt for too long.','妮娅把熨斗面朝下放在衬衫上太久，衣领因此被烫焦。','The iron scorched the collar / when it stayed face down / too long.','scorch.s1 指用干热烧坏或烫焦物体表面。','衣领被熨斗烫焦。'),C('scorch.s2','（植物）枯萎','Weeks of hot, dry wind scorched the young leaves along the exposed hillside.','数周的炎热干风使裸露山坡上的嫩叶枯焦。','Hot, dry wind scorched the leaves / along the exposed hillside / for weeks.','scorch.s2 指强烈日晒或风使植物干枯受损。','干热风损伤嫩叶。')],M('The iron scorched the collar by cooling it gently and leaving the fabric completely undamaged.','The iron scorched the collar by burning its surface with heat.','表面未受损就没有被烫焦。','meaning'),[q('What damaged Nia’s collar?','the hot iron left on it too long','a cold glass of water','a strong perfume','衣领被放置过久的热熨斗烫焦。',1,'context'),q('What happened to the hillside leaves?','hot, dry wind damaged them','heavy shade made them grow taller','they were carefully watered','嫩叶被炎热干风损伤。',2,'context'),q('What does scorch mean in the iron example?','to burn a surface with dry heat','to cool fabric rapidly','to sew a collar','此处 scorch 指用热量烫焦表面。',1,'meaning'),q('What does scorch mean in the leaf example?','to dry and damage plants through strong heat or wind','to plant seeds in a hillside','to protect leaves from sunlight','此处 scorch 指使植物因热风而枯损。',2,'meaning')]);
P('scorching','Scorching is the present participle of scorch and an adjective meaning extremely hot or, figuratively, fierce and harshly critical.',[C('scorching.s1','灼热的','They crossed the beach at noon under a scorching sun and found no shade until the pier.','他们在正午灼热的阳光下穿过海滩，直到码头才找到阴凉处。','They crossed the beach / under a scorching sun / at noon.','scorching.s1 指热得仿佛会灼伤人的酷热。','正午烈日下海滩十分酷热。'),C('scorching.s2','激烈的；严厉的','The reviewer published a scorching criticism of the company’s unsafe design and unsupported claims.','评论者对该公司不安全的设计和缺乏依据的说法发表了尖锐批评。','The reviewer published scorching criticism / of the unsafe design / and unsupported claims.','scorching.s2 比喻猛烈、尖锐或严厉的。','评论对设计提出尖锐批评。')],M('The hikers walked comfortably under a scorching sun because it was cool and shaded.','The hikers struggled in the extreme heat of the scorching sun.','scorching 表示酷热，与凉爽荫蔽相反。','meaning'),[q('When did the travelers cross the beach?','at noon under the scorching sun','at midnight in a snowstorm','at dawn in cool shade','他们在正午灼热阳光下穿过海滩。',1,'context'),q('What did the reviewer publish?','harsh criticism of the unsafe design','a warm compliment about every claim','a weather forecast','评论者发表了对不安全设计的尖锐批评。',2,'context'),q('What does scorching mean about the sun?','extremely hot','slightly cool','completely dark','scorching 描述阳光时表示灼热的。',1,'meaning'),q('What does scorching mean about criticism?','fierce and harshly critical','mild and approving','unrelated to the subject','scorching 描述批评时表示猛烈尖锐。',2,'meaning')]);
P('score','Score comes from Old Norse skor (“notch, tally”); it can mean points, to gain points, twenty, written music, or a mark cut into a surface.',[C('score.s1','得分；比分','The final score was 3–2 after the home team defended its lead in the last minute.','主队在最后一分钟守住领先优势，最终比分是3比2。','The final score was 3–2 / after the home team / defended its lead.','score.s1 指比赛中选手或队伍获得的分数。','终场比分显示双方得分。'),C('score.s2','得分；记分','Mina scored the winning goal just before the referee blew the final whistle.','米娜在裁判吹响终场哨前打进制胜球。','Mina scored the winning goal / just before / the final whistle.','score.s2 作动词，指在比赛或测试中赢得一分或进球。','米娜打进制胜球。'),C('score.s3','二十','The old ballad says that a score of years passed before the lost heir returned home.','古老民谣说，失踪的继承人过了二十年才回家。','A score of years passed / before the heir / returned home.','score.s3 作数量词时指二十。','一 score 年即二十年。'),C('score.s4','总谱；配乐','The composer finished the score for the film before the orchestra began recording it.','作曲家在乐团开始录音前完成了电影配乐总谱。','The composer finished the film score / before the orchestra / began recording.','score.s4 指为电影、戏剧或乐团写成的音乐。','电影配乐总谱先于录制完成。'),C('score.s5','划痕；刻痕','A deep score across the wooden door showed where the metal latch had scraped it.','木门上一道深刻痕显示金属门闩曾在那里刮擦。','A deep score crossed the door / where the latch / had scraped the wood.','score.s5 指表面上切出的一道线或痕迹。','门闩在木门上留下刻痕。')],M('The team celebrated a final score of 3–2 even though no points had been counted and the result was 0–0.','The final score was 3–2, the points recorded at the end of play.','score 作名词表示实际记录的比分；0–0 并非 3–2。','meaning'),[q('What was the final score?','3–2','0–0','2–3','主队最终以3比2获胜。',1,'context'),q('Who scored the winning goal?','Mina','the referee','the composer','米娜打进制胜球。',2,'context'),q('What does score mean in “a score of years”?','twenty','three','one hundred','短语 a score 指二十。',3,'meaning'),q('What did the composer finish?','the written music for the film','a list of the team’s points','a scratch on the door','composer 完成的是电影配乐总谱。',4,'context')]);
P('scorer','Scorer is formed from score and the agent suffix -er; it means a player who gains points or goals, or a person who records them.',[C('scorer.s1','得分者','The scorer celebrated after heading the winning goal into the net during stoppage time.','补时阶段，得分者头球攻入制胜球后庆祝。','The scorer celebrated / after heading the winning goal / into the net.','scorer.s1 指在比赛中获得分数或进球的选手。','球员攻入制胜球。'),C('scorer.s2','记分员','The official scorer checked the inning-by-inning sheet before signing the baseball results.','记分员签署棒球赛果前核对了逐局记录表。','The official scorer checked the sheet / inning by inning / before signing.','scorer.s2 指负责记录比赛得分的人。','工作人员核对逐局比分。')],M('The official scorer played on the field and headed the winning goal, while the actual player only recorded the sheet.','The player scored the goal; the official scorer recorded the result.','踢球进球的是球员；记录比分的是记分员。','meaning'),[q('What did the scorer do during stoppage time?','headed the winning goal into the net','signed the baseball sheet','blew the final whistle','得分者头球攻入制胜球。',1,'context'),q('What did the official scorer check?','the inning-by-inning results sheet','the film music score','the wooden door’s scratch','记分员核对了逐局赛果表。',2,'context'),q('What is a scorer in the first example?','a player who gains a point or goal','a person who writes film music','a referee who ends every match','第一句 scorer 指获得进球的球员。',1,'meaning'),q('What is an official scorer?','a person who records points or results','a player who refuses to join the game','a spectator who predicts the weather','official scorer 指负责记录比赛得分的人。',2,'meaning')]);
P('scorn','Scorn comes from Old French esc(h)arnir (“mock, disdain”); it is contempt for someone or something, or the act of showing such contempt.',[C('scorn.s1','轻蔑；鄙视','Her scorn for the dishonest proposal was clear when she refused even to discuss it.','她对那项不诚实提案的鄙视显而易见，甚至拒绝讨论。','Her scorn for the proposal was clear / when she refused / to discuss it.','scorn.s1 指认为某人或某事不值得尊重的强烈感情。','她认为提案不值得尊重。'),C('scorn.s2','鄙视；不屑于','The editor scorned the rumor and demanded verifiable evidence before printing a claim.','编辑不屑于接受这则传言，并要求在刊发说法前提供可核实的证据。','The editor scorned the rumor / and demanded / verifiable evidence.','scorn.s2 作动词，指表示蔑视，或傲然拒绝某事。','编辑拒绝接受传言。')],M('Her scorn for the dishonest proposal was shown by eagerly praising it as fair and trustworthy.','Her scorn was shown by rejecting the dishonest proposal.','赞扬提案为公平可信并非鄙视。','meaning'),[q('How did she show scorn for the proposal?','she refused even to discuss it','she praised it as honest','she signed it immediately','她拒绝讨论提案，表明鄙视。',1,'context'),q('What did the editor demand?','verifiable evidence','a rumor from an anonymous source','a new film score','编辑要求提供可核实的证据。',2,'context'),q('What is scorn in the first example?','a strong feeling of contempt','a score in a sports match','an official written report','第一句 scorn 指强烈的轻蔑感。',1,'meaning'),q('What does scorn mean as a verb here?','to show contempt for or proudly reject something','to record a game’s points','to lift something with a shovel','此处 scorn 作动词，指鄙视或不屑接受。',2,'meaning')]);
P('scornful','Scornful is formed from scorn and -ful; it means showing contempt or using insulting, dismissive words.',[C('scornful.s1','轻蔑的；鄙夷的','He gave a scornful glance at the proposal, as if it were beneath serious consideration.','他轻蔑地瞥了一眼提案，仿佛它根本不值得认真考虑。','He gave a scornful glance / at the proposal / as if it were beneath notice.','scornful.s1 指表现出认为某人或某事毫无价值的态度。','他的神情流露出轻蔑。'),C('scornful.s2','言辞尖刻不屑的','Her scornful remarks called the evidence worthless and dismissed the witnesses as fools.','她尖刻不屑地称证据毫无价值，并把证人斥为愚人。','Her scornful remarks dismissed the evidence / and insulted / the witnesses.','scornful.s2 指使用侮辱、贬低他人的言语。','她的言语贬低证据和证人。')],M('He gave a scornful glance that showed deep respect and admiration for the proposal.','He gave a scornful glance that showed he thought the proposal unworthy.','scornful 表达轻蔑，并非尊重赞赏。','meaning'),[q('What attitude did his glance show?','he thought the proposal unworthy','he admired the proposal deeply','he had not seen the proposal','他的眼神表明他认为提案不值得认真考虑。',1,'context'),q('What did her remarks do?','dismissed the evidence and insulted the witnesses','praised the evidence and thanked the witnesses','recorded the game score','她的话贬低证据并侮辱证人。',2,'context'),q('What does scornful mean in the glance example?','showing contempt','showing gratitude','showing uncertainty about a score','此处 scornful 指表现出轻蔑。',1,'meaning'),q('What are scornful remarks?','insulting words that dismiss others','neutral notes that list times','polite questions seeking clarification','scornful remarks 是侮辱、贬低他人的话。',2,'meaning')]);
P('scorpion','Scorpion comes through Old French from Latin scorpio and Greek skorpios; it is an arachnid with a venomous sting at the end of its tail.',C('scorpion.s1','蝎','The desert guide spotted a scorpion under the flat stone and warned the hikers not to touch it.','沙漠向导在扁平石块下发现一只蝎子，提醒徒步者不要触碰。','The guide spotted a scorpion / under a flat stone / and warned the hikers.','scorpion.s1 是尾部末端带有毒刺的蛛形纲动物。','蝎子藏在石下，向导提醒不要碰。'),M('The hikers identified the scorpion as a harmless plant with leaves and no tail or sting.','The hikers identified the scorpion as a tailed arachnid with a venomous sting.','蝎子是有尾部毒刺的蛛形动物，不是植物。','meaning'),[q('Where did the guide see the scorpion?','under a flat stone','inside a schoolroom','on the film screen','向导在扁平石块下发现蝎子。',1,'context'),q('What did the guide tell the hikers?','not to touch it','to pick it up by its tail','to feed it a sandwich','向导提醒徒步者不要触碰蝎子。',1,'context'),q('What is a scorpion?','an arachnid with a venomous tail sting','a small shovel for grain','a kind of scoring official','scorpion 是尾部带毒刺的蛛形动物。',1,'meaning'),q('Which creature is a scorpion?','a desert arachnid with a segmented tail and sting','a leafless tree branch','a fish that records scores','有分节尾部和毒刺的沙漠蛛形动物是蝎子。',1,'context')]);
P('Scotch','Scotch is an adjectival form of Scots and is used in fixed names; as a noun it commonly means whisky distilled in Scotland.',[C('Scotch.s1','苏格兰威士忌','They served a small glass of Scotch distilled in Scotland after the formal dinner.','正式晚宴后，他们端上一小杯苏格兰蒸馏威士忌。','They served a small glass of Scotch / distilled in Scotland / after dinner.','Scotch.s1 指在苏格兰蒸馏的威士忌，尤其是用麦芽大麦酿制的酒。','酒在苏格兰蒸馏。'),C('Scotch.s2','苏格兰的','The museum displayed a Scotch bonnet beside other traditional names connected with Scotland.','博物馆把一顶苏格兰式帽子与其他苏格兰传统名称物品一同展出。','The museum displayed a Scotch bonnet / among names / connected with Scotland.','Scotch.s2 主要见于与苏格兰有关的固定名称中。','Scotch bonnet 是与苏格兰相关的固定名称。')],M('The bartender called the drink Scotch even though it was distilled in Scotland’s neighbor and had no connection to Scotland.','The bartender served Scotch distilled in Scotland.','Scotch whisky 的关键关联是产自苏格兰。','meaning'),[q('What did they drink after dinner?','a small glass of whisky distilled in Scotland','a glass of rainwater','a bowl of grain measured by a scoop','他们晚宴后喝了一小杯苏格兰蒸馏威士忌。',1,'context'),q('What item did the museum display?','a Scotch bonnet','a baseball score sheet','a desert scorpion','博物馆展出了一顶名为 Scotch bonnet 的帽子。',2,'context'),q('What does Scotch mean as a noun here?','whisky distilled in Scotland','a person who records a score','a tool for lifting grain','此处 Scotch 名词指苏格兰威士忌。',1,'meaning'),q('How is Scotch used in “Scotch bonnet”?','as part of a fixed name connected with Scotland','as a verb meaning to burn a collar','as a number meaning twenty','Scotch bonnet 中 Scotch 是与苏格兰有关的固定名称成分。',2,'meaning')]);
P('Scotland','Scotland is the English name of the country, from Old English Scotland, “land of the Scots”; it forms the northern part of Great Britain.',[C('Scotland.s1','苏格兰（国家）','Scotland occupies the northern part of Great Britain, with Edinburgh as its capital.','苏格兰位于大不列颠北部，首府是爱丁堡。','Scotland occupies the north / of Great Britain / and has Edinburgh as its capital.','Scotland.s1 指组成大不列颠北部的国家。','句中指国家及其首府。'),C('Scotland.s2','苏格兰队；苏格兰一方','Scotland scored twice in the second half, and its national team won the international match.','下半场苏格兰队进了两球，赢得了这场国际比赛。','Scotland scored twice / in the second half / and won the match.','Scotland.s2 可转指代表苏格兰参赛的国家队或一方。','体育报道以国家名代称国家队。')],M('Scotland is the country in the southern part of Great Britain, and Edinburgh is its capital.','Scotland is the country in the northern part of Great Britain, with Edinburgh as its capital.','苏格兰位于大不列颠北部，不是南部。','meaning'),[q('Where is Scotland?','in the northern part of Great Britain','in the southern part of Australia','on an island in the Pacific','苏格兰位于大不列颠北部。',1,'context'),q('What did Scotland do in the match?','scored twice in the second half','lost its capital city','recorded a film score','此处 Scotland 指国家队，下半场进了两球。',2,'context'),q('What is Scotland in the first example?','a country forming northern Great Britain','a city in southern England','a sports official','第一句 Scotland 指组成大不列颠北部的国家。',1,'meaning'),q('What does Scotland refer to in the sports report?','the national team representing the country','the country’s capital building','a whisky served after dinner','体育报道中的 Scotland 指代表该国的国家队。',2,'meaning')]);
P('scotsman','Scotsman is formed from Scot and the suffix -sman; it means a male native or inhabitant of Scotland.',C('scotsman.s1','苏格兰男人','The Scotsman described how his family had lived near Inverness for several generations.','这名苏格兰男人讲述了他的家族世世代代住在因弗内斯附近。','The Scotsman described his family / which had lived near Inverness / for generations.','scotsman.s1 指苏格兰的男性本地人或居民。','说话者是住在苏格兰多代的男子。'),M('The Scotsman was a woman born and raised in another country with no connection to Scotland.','The Scotsman was a male native or inhabitant of Scotland.','该词明确指苏格兰男性本地人或居民。','meaning'),[q('Where had the Scotsman’s family lived?','near Inverness','in the desert','beside a film studio','他的家族世世代代住在因弗内斯附近。',1,'context'),q('For how long had the family lived there?','for several generations','for one afternoon','for no time at all','他的家族在那里住了好几代。',1,'context'),q('What does Scotsman mean?','a male native or inhabitant of Scotland','any person who records a score','a woman visiting Scotland briefly','Scotsman 指苏格兰男性本地人或居民。',1,'meaning'),q('Who could be called a Scotsman?','a man born or living in Scotland','a woman from another country','a male referee from any nation','出生于或居住在苏格兰的男子可称为 Scotsman。',1,'context')]);
P('scour','Scour comes through Middle English from Old Norse skura (“wash, scrub”); it means to clean something thoroughly by hard rubbing.',C('scour.s1','刷洗干净；擦亮','Marta scoured the roasting pan with a stiff brush until the baked-on sauce disappeared.','玛尔塔用硬毛刷彻底刷洗烤盘，直到烤干的酱汁消失。','Marta scoured the roasting pan / with a stiff brush / until it was clean.','scour.s1 指用力擦洗以彻底清洁。','她用硬刷刷净烤盘。'),M('Marta scoured the roasting pan by leaving it dirty and refusing to rub or wash it.','Marta scoured the roasting pan by scrubbing it hard with a brush.','scour 表示用力擦洗；放着不洗不算清洁。','meaning'),[q('What did Marta clean?','a roasting pan','a film score','a desert hillside','玛尔塔刷洗的是烤盘。',1,'context'),q('What tool did she use?','a stiff brush','a music stand','a scarf','她用硬毛刷刷洗烤盘。',1,'context'),q('What does scour mean?','to clean thoroughly by hard rubbing','to criticize someone angrily','to score a goal','scour 指用力擦洗以彻底清洁。',1,'meaning'),q('Which action is scouring?','scrubbing baked-on sauce from a pan with a brush','looking at a dirty pan without touching it','measuring grain with a scoop','用刷子擦掉烤盘上的干酱汁属于 scour。',1,'context')]);
P('scourge','Scourge is from Old French escorge (“whip”), ultimately from Latin excoriare (“flay”); it means a cause of great suffering or to punish severely.',[C('scourge.s1','祸害；灾难','For decades, the invasive beetle was a scourge of orchards, destroying trees across the valley.','几十年来，这种入侵甲虫一直是果园的祸害，摧毁了整个山谷的树木。','The beetle was a scourge of orchards / destroying trees / across the valley.','scourge.s1 指长期造成极大痛苦或麻烦的人、事物或疾病。','甲虫长期破坏果园。'),C('scourge.s2','鞭笞；折磨','The unjust ruler scourged prisoners for refusing to confess to crimes they had not committed.','暴虐的统治者因囚犯拒绝承认未曾犯下的罪行而鞭笞他们。','The ruler scourged prisoners / for refusing to confess / to false charges.','scourge.s2 作动词，指严厉惩罚或折磨某人。','囚犯因拒绝虚假认罪而受惩罚。')],M('The beetle was called a scourge of orchards because it protected every tree from damage and ended the infestation.','The beetle was a scourge because it destroyed orchard trees.','保护树木并消除虫害不会成为果园祸害。','meaning'),[q('Why was the beetle a scourge of orchards?','it destroyed trees across the valley','it protected trees from insects','it kept the fruit cool','入侵甲虫摧毁山谷果树，因此成为祸害。',1,'context'),q('Why did the ruler scourge the prisoners?','they refused to confess to crimes they had not committed','they won a sports match','they cleaned the cell','统治者因囚犯拒绝承认虚假罪行而惩罚他们。',2,'context'),q('What is a scourge in the orchard example?','a cause of great trouble or suffering','a tool for measuring grain','a written musical composition','此处 scourge 指造成严重麻烦的祸害。',1,'meaning'),q('What does scourge mean as a verb?','to punish or trouble someone severely','to praise a person publicly','to clean a pan with a brush','scourge 作动词指严厉惩罚或折磨。',2,'meaning')]);
P('scout','Scout is from Middle French escoute (“listener, spy”), from écouter (“listen”); it can be a person or vehicle sent ahead, a Scout member, or the act of searching.',[C('scout.s1','侦察员；侦察机','A scout rode ahead of the expedition to report whether the bridge was safe to cross.','一名侦察员骑在队伍前方，去报告桥梁是否安全可通行。','A scout rode ahead / to report / whether the bridge was safe.','scout.s1 指被派到前方收集情报的人或车辆。','侦察员先行检查桥梁。'),C('scout.s2','童子军成员','As a Scout, Elena learned first aid and helped her troop pack supplies for the camping trip.','作为一名童子军成员，埃琳娜学习了急救，并帮助小队打包露营用品。','As a Scout, Elena learned first aid / and helped her troop / pack supplies.','scout.s2 指童子军协会的成员。','她是童子军小队成员。'),C('scout.s3','侦察；物色；寻找','The club sent an agent to scout local schools for a goalkeeper with quick reflexes.','俱乐部派了一名球探到当地学校物色反应敏捷的守门员。','The club sent an agent to scout schools / for a goalkeeper / with quick reflexes.','scout.s3 作动词，指搜寻某地或群体以寻找有用的人或物。','球探到学校寻找守门员。')],M('The club sent an agent to scout schools by refusing to look for any players or visit the area.','The agent scouted local schools to look for a goalkeeper.','scout 作动词表示搜寻、物色；拒绝寻找并不符合。','meaning'),[q('What did the scout check ahead of the expedition?','whether the bridge was safe','the film’s written score','the location of a roasting pan','侦察员先行查看桥梁是否安全。',1,'context'),q('What did Elena do as a Scout?','learned first aid and packed camping supplies','scored a goal for the club','scoured a pan','埃琳娜作为童子军成员学习急救并打包露营用品。',2,'context'),q('What does scout mean as a verb in the club example?','to search places for a useful player','to punish a player severely','to record the match score','此处 scout 指到学校寻找合适球员。',3,'meaning'),q('Which person is a scout in sense 1?','someone sent ahead to gather information','a person who writes music for a film','a person who refuses to examine a bridge','被派到前方收集情报的人是 scout。',1,'meaning')]);
P('scowl','Scowl is of uncertain origin and is recorded in English for a frowning, angry look or the act of making one.',[C('scowl.s1','怒容；皱眉','A deep scowl appeared on the inspector’s face when he found the safety seal broken.','检查员发现安全封条破损时，脸上露出深深的怒容。','A deep scowl appeared / on the inspector’s face / when the seal was broken.','scowl.s1 指表现出愤怒或恼火的面部表情。','封条破损使检查员皱起眉头。'),C('scowl.s2','怒视；皱眉','The child scowled at the noisy dog until its owner led it away from the library door.','孩子怒视着吵闹的狗，直到主人把它领离图书馆门口。','The child scowled at the dog / until its owner / led it away.','scowl.s2 作动词，指皱眉或带着怒气瞪视某人。','孩子皱眉怒视吵闹的狗。')],M('A scowl appeared on the inspector’s face as he smiled warmly and approved the broken seal.','A scowl appeared as the inspector frowned angrily at the broken seal.','微笑并认可并未表现怒容。','meaning'),[q('What caused the inspector’s scowl?','he found the safety seal broken','he received a perfect score','he saw a clean roasting pan','检查员发现安全封条破损后露出怒容。',1,'context'),q('At what did the child scowl?','the noisy dog','the library’s quiet sign','the dog’s empty water bowl','孩子怒视吵闹的狗。',2,'context'),q('What is a scowl?','an angry or annoyed expression','a smile of approval','a written score for a film','scowl 名词指愤怒或恼火的表情。',1,'meaning'),q('What does scowl mean as a verb?','to look at someone with an angry frown','to wave cheerfully at a neighbor','to clean a metal pan','scowl 作动词指皱眉怒视。',2,'meaning')]);
P('scraggly','Scraggly is an informal variant of scraggy, related to scrag (“lean, rough-looking”); it describes something rough, irregular, and sparse.',C('scraggly.s1','蓬乱的；稀疏不齐的','A scraggly beard grew along his jaw, with thin uneven patches between the longer hairs.','他的下颌长着一把蓬乱的胡子，较长的毛发之间夹杂着稀疏不齐的区域。','A scraggly beard grew / along his jaw / in thin uneven patches.','scraggly.s1 形容头发、胡须或植物等粗乱、不齐且稀疏。','胡须稀疏且长得不均匀。'),M('The gardener called the hedge scraggly even though every branch was dense, even, and neatly trimmed.','The gardener called the hedge scraggly because its growth was sparse and irregular.','枝叶浓密、整齐修剪的树篱不符合 scraggly 的含义。','meaning'),[q('What was scraggly?','the uneven beard along his jaw','the smooth clean-shaven face','the inspector’s safety seal','他下颌的胡须蓬乱且不均匀。',1,'context'),q('How was the hair distributed?','in thin uneven patches','in a dense, perfectly even line','not at all because he had shaved','胡须分布稀疏且不均匀。',1,'context'),q('What does scraggly describe?','rough, irregular, and sparse growth','a smooth and carefully polished surface','a precise record of points','scraggly 描述粗乱、不齐且稀疏的生长状态。',1,'meaning'),q('Which hedge is scraggly?','one with sparse uneven branches','one trimmed into a dense even wall','one with no irregular or thin growth','枝条稀疏不齐的树篱可称为 scraggly。',1,'context')]);
})();
